quests[46064] = { id = 46064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So ist das Leben", description = "Mrrga!\n\n<Eure Kaulquappe kauert sich ängstlich in einem Versteck zusammen, als sie den schattenhaften Umriss eines riesigen vorbeischwimmenden Orcas aus der Westklamm erspäht.>\n\nMrrga... Mrrga...", sourceObjective = "Tötet Mrrga.", sourceObjectiveStatus = "unverified-source-field" }
quests[46065] = { id = 46065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein unmöglicher Feind", description = "{name}! Wir haben soeben eine Nachricht vom Rat der Sechs erhalten. Sie haben Agatha gefunden!\n\nModera möchte Euch mittels dieses Abbildkristalls informieren.\n\nViel Glück!", sourceObjective = "Sprecht mit Kriegsrätin Victoria, um zur Höhle der Wichtelmutter teleportiert zu werden, und besiegt dort Agatha.", completion = "Ich habe von Agathas Niedergang sowie von ihrem Plan zu Infiltrierung der Kirin Tor gehört. Ohne Eure prompte Maßnahmen hätten ihre Sayaad möglicherweise irreparablen Schaden verursacht.\n\nMeine Magier sind damit beschäftigt, Agathas verbleibende Verbündete zu jagen, doch der wahre Sieg des Tages ist Euer, {name}.\n\nDie Kirin Tor danken Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[46066] = { id = 46066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein teuflisches Flattern" }
quests[46068] = { id = 46068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlägerzähmung" }
quests[46069] = { id = 46069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des Titels würdig", description = "Hochlord, Lord Grayson Schattenbruch möchte mit Euch über eine wichtige Angelegenheit sprechen.\n\nBitte sucht ihn an der Kapelle des Hoffnungsvollen Lichts in Eurer Ordenshalle auf, sobald Euch dies möglich erscheint.", sourceObjective = "Sprecht in Eurer Ordenshalle mit Lord Grayson Schattenbruch.", completion = "Hochlord, ich möchte mit Euch über die Beschaffung eines neuen Reittiers sprechen...", sourceObjectiveStatus = "unverified-source-field" }
quests[46070] = { id = 46070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vorbereitungen laufen", description = "Wie Ihr Euch vielleicht erinnert oder auch nicht, habe ich früher jungen Paladinen dabei geholfen, ihr erstes gepanzertes Reittier zu erhalten.\n\nDas war eine mühsame Aufgabe, bei der man monatelang Materialien sammeln und kreuz und quer durch Azeroth reisen musste.\n\nZum Glück haben die Zeiten sich geändert und wir haben jetzt die meisten dieser Materialien verfügbar. Gleichwohl möchte ich Euch helfen, ein neues Reittier zu bekommen, eins, das Eurem Titel als Hochlord angemessen ist.\n\nDamit wir beginnen können, müsst Ihr nur ein Geschirr für uns besorgen. Eins, das robust und schwer ist.", sourceObjective = "Beschafft ein Steinbalgledergeschirr von einem Lederverarbeiter. Ihr dürft es auch aus dem Auktionshaus beschaffen, wenn Ihr kein Lederverarbeiter seid oder keinen kennt.", progress = "Wie läuft die Suche nach dem Geschirr? Habt Ihr schon etwas Passendes gefunden?", completion = "<Grayson untersucht das Geschirr.>\n\nDas ist... nun, ein guter Anfang, Hochlord. Aber ich glaube, wir müssen das noch ein wenig verstärken.", sourceObjectiveStatus = "unverified-source-field" }
quests[46071] = { id = 46071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hammer von Dalaran", description = "Wenn wir wollen, dass dieses Geschirr des Rosses würdig ist, das es tragen soll, müssen wir es aufwerten. Jetzt ist es gerade gut genug, damit Ihr nicht von Eurem Reittier geworfen werdet.\n\nSprecht mit Alard Schmied in Dalaran. Wie der Name vermuten lässt, ist er ein ausgezeichneter Schmied und wird wissen, wie man dieses Geschirr verbessert, damit es unseren Ansprüchen genügt.", sourceObjective = "Sprecht mit Alard Schmied in Dalaran.", completion = "Seid gegrüßt, Hochlord. Womit kann ich Euch behilflich sein?\n\n<Ihr erklärt Alard, was Ihr benötigt, und er betrachtet das Geschirr.>\n\nIch verstehe. Ich kann Euch sicherlich dabei helfen, das hier aufzuwerten, aber zunächst benötige ich ein paar Dinge.", sourceObjectiveStatus = "unverified-source-field" }
quests[46072] = { id = 46072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voll teuflisch" }
quests[46073] = { id = 46073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihre Garnison brechen" }
quests[46074] = { id = 46074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Leder zu Legendär", description = "Dann lasst uns anfangen, ja? Ich meine, ich werde die ganze Arbeit machen, aber Ihr dürft zusehen!\n\n<Alard grinst Euch breit an und beginnt mit seiner Arbeit.>", sourceObjective = "Lasst Alard das Geschirr aufwerten und kehrt damit zu Lord Grayson Schattenbruch in Eurer Ordenshalle zurück.", progress = "Wie ist es gelaufen? Konnte Alard das Geschirr aufwerten?", completion = "<Grayson begutachtet das Geschirr.>\n\nDas ist perfekt. Genau, was ich von Alard erwartet habe. Jetzt, da wir alles haben, bleibt nur noch eine Aufgabe.", sourceObjectiveStatus = "unverified-source-field" }
quests[46075] = { id = 46075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reliktjagd" }
quests[46076] = { id = 46076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhelose Geister" }
quests[46077] = { id = 46077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonenversklavte Geister" }
quests[46078] = { id = 46078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heilig: Die Untersuchung von Bradenbach", description = "Wir haben an der Küste gefälschte Befehle entdeckt. Sie weisen einen dämonischen Einfluss auf. Er lässt den Leser an ihre Rechtmäßigkeit glauben. Den Befehlen zufolge soll die Rabenwehr eine \"dämonische Enklave\" südlich ihrer Mauern angreifen. Dabei kann es sich nur um eine Enklave handeln: Bradenbach!\n\nKönnte es sein, dass dies die Untoten dazu treiben soll, Bradenbach anzugreifen? Ihr solltet Euch sofort dorthin begeben und sie entweder warnen oder ihnen Unterstützung anbieten.", sourceObjective = "Begebt Euch nach Bradenbach in Val'sharah.", completion = "Ein wenig spät für eine Warnung, oder? Dennoch freut es uns, dass man uns noch nicht ganz vergessen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[46079] = { id = 46079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe an vorderster Front", description = "Als wir uns hier niedergelassen haben, war die Rabenwehr nur ein stiller und gruseliger Ort, den wir mieden. Dann kehrten die Elfen aus dem Reich des Todes zurück. Mit Eurer Hilfe, dachten wir, wäre alles im Lot. Doch nun scheint es mir, als ob uns eine ganze Armee angreift!\n\nWir könnten mehr Heiler an unseren Verteidigungslinien gebrauchen. Es kommen immer mehr Untote und mit jeder Welle bleiben uns weniger Beschützer. Jegliche Hilfe für unsere Verwundeten wäre äußerst willkommen!", sourceObjective = "Unterstützt die Verwundeten an den östlichen, westlichen und südlichen Verteidigungslinien von Bradenbach.", completion = "Am heutigen Tage habt Ihr viele Leben gerettet, {class}. Bradenbach dankt Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[46080] = { id = 46080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstummen der Geister", description = "Es steht ein massiver Angriff auf Bradenbach bevor. Aber ich glaube, dass wir die Situation entschärfen können, bevor sie wirklich gefährlich wird.\n\nWährend wir uns um die Kommandanten kümmern, sollten wir so viele ruhelose Geister töten wie möglich.\n\nSobald wir ihre Anführer ausgeschaltet und ihre Truppen dezimiert haben, können wir nach Erdris Dorn suchen.", sourceObjective = "Tötet auferstandene Elfen und Geister nahe Bradenbach.", progress = "Man kann Euch ansehen, dass Ihr vielen den \"Frieden\" gebracht hat, {class}.", completion = "Wir wissen, dass diese Geister fehlgeleitet sind, doch zu so einer Zeit sind die Lebenden wichtiger als die Toten.\n\nDies sollte die Angriffe für eine Weile eindämmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46081] = { id = 46081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Leder zu Legendär", description = "In letzter Zeit habe ich mit dem Erz dieses Landes gearbeitet, das Leystein genannt wird. Ich habe herausgefunden, dass es von bemerkenswerter Stärke und Haltbarkeit ist. Wir werden hierfür eine Menge davon brauchen.\n\nEs gibt noch Teufelsschiefer, aber der ist wahrscheinlich zu verderbt für das, was Ihr mit diesem Geschirr vorhabt.\n\nWisst Ihr, ich verziere meine Arbeiten auch gerne mit etwas Funkelndem wie einem Edelstein. Wie ich höre, funkeln Säbleraugen ganz besonders schön. Bringt mir doch auch eins davon mit, ja?", sourceObjective = "Beschafft 50 Brocken Leysteinerz und 1 Säblerauge.", sourceObjectiveStatus = "unverified-source-field" }
quests[46082] = { id = 46082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr von Schattensang", description = "Sehr gut! Unsere Verteidiger kommen nun viel besser zurecht, dank Euch. Das ist auch gut so, denn wir brauchen eine Pause!\n\nAllerdings sahen wir eine große Gruppe von noch übleren Wiederauferstandenen vom Bauernhof kommen. Sie hätten uns schwer zu schaffen gemacht, aber dieser Schattensang ist zurückgekommen und hat sie alle getötet. Er hält ihre Verstärkung zurück, die von der Festung kommt.\n\nIch schätze, er könnte etwas Hilfe brauchen. Wir können hier ausharren, bis Ihr und Schattensang alles im Griff habt.", sourceObjective = "Findet Jarod Schattensang außerhalb von Bradenbach in Val'sharah.", completion = "Ich hatte gehofft, dass die Stadt endlich Frieden gefunden hätte nach all dem, was wir hier durchgemacht haben. Irgendwie wurden die rastlosen Toten in Zorn versetzt. Wir müssen das beenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[46083] = { id = 46083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eins nach dem anderen", description = "In letzter Zeit habe ich mit dem Erz dieses Landes gearbeitet, das Leystein genannt wird. Ich habe herausgefunden, dass es von bemerkenswerter Stärke und Haltbarkeit ist. Wir werden hierfür eine Menge davon brauchen.\n\nEs gibt noch Teufelsschiefer, aber der ist wahrscheinlich zu verderbt für das, was Ihr mit diesem Geschirr vorhabt.\n\nWisst Ihr, ich verziere meine Arbeiten auch gerne mit etwas Funkelndem wie einem Edelstein. Ich habe gehört, dass die Elfen von Suramar besonders schöne Exemplare haben. Vielleicht könntet Ihr einen davon für dieses Projekt besorgen.", sourceObjective = "Beschafft 25 Brocken Leysteinerz und einen suramarischen Saphir.", progress = "Ich bezweifle, dass Ihr Schwierigkeiten haben werdet, Leystein zu bekommen, doch der Saphir dürfte etwas schwieriger zu beschaffen sein.", completion = "Ihr habt alles! Dann können wir ja jetzt Euer Geschirr aufwerten.\n\nSagt niemals, ein Schmied könne die Arbeit eines Lederverarbeiters nicht aufwerten, sage ich immer. Ich meine, niemals. Ich meine... Nun, Ihr wisst schon, was ich meine.", sourceObjectiveStatus = "unverified-source-field" }
quests[46089] = { id = 46089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor aller Augen verborgen", description = "Seid gegrüßt, Schattenklinge.\n\nIch hoffe, Ihr seid nicht allzu verärgert, dass ich ohne Euch angefangen habe. Ich habe leichte Schwierigkeiten, mich angesichts der hirnlosen Untoten zu beherrschen.\n\nJa, Ihr habt mich richtig verstanden. Taerir, genau der Taerir, der jetzt seit vielen Monaten in der Halle der Schatten gestanden hat, war die untote Schachfigur eines Schreckenslords.\n\nUnd es gibt noch mehr von ihnen. Sie sind in unseren Städten, sie steigen in den Rängen der Aristokratie auf, legen an Macht und Einfluss zu und sind kaum aufzuspüren.", sourceObjective = "Ermordet die infiltrierenden Homunculi.", completion = "Wir haben den Dämonen gezeigt, warum sie die Dunkelheit wirklich fürchten sollten. Jetzt hat Lord Rabenholdt etwas aus seiner persönlichen Sammlung für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[46090] = { id = 46090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rare Elite 01" }
