quests[46102] = { id = 46102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rare Elite 13" }
quests[46103] = { id = 46103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schreckensinfiltratoren", description = "Schattenklinge, ein Rabe hat uns mit verstörenden Neuigkeiten erreicht.\n\nEiner der Unsrigen, ein Verbündeter, der in unserer Halle der Schatten wandelte, war nicht, wer er zu sein schien.\n\nIch glaube, Lilian hat bereits damit begonnen, die Leiche zu sezieren. Ihr solltet Euch beeilen.", sourceObjective = "Sprecht mit Lilian Voss in der Halle der Schatten.", completion = "Man weiß wirklich nie, ob ein Verbündeter eine untote Schachfigur unter der Kontrolle eines Schreckenslords ist, bis man ihn aufschneidet.", sourceObjectiveStatus = "unverified-source-field" }
quests[46104] = { id = 46104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Giftigkeit der Arachniden" }
quests[46105] = { id = 46105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überlegenheit der Arachniden" }
quests[46106] = { id = 46106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ab mit den Köpfen", description = "Erdris Dorn war einer der Schlüsselkommandanten von Rabenkrones Streitmacht. Dass er uns mit der Legion verwechselt, macht mich wahrhaft traurig. Er wird als Gegner nicht leicht zu besiegen sein.\n\nWir müssen dafür sorgen, dass seine Staffelführer keinen konzentrierten Angriff auf Bradenbach durchführen können. Wenn wir sie erledigen und damit seine Truppen aufhalten, sollten wir genug Zeit haben, um ihn zu finden und auszuschalten. Lasst uns die grausame Aufgabe angehen.", sourceObjective = "Tötet die auferstandenen Staffelführer in Bradenbach.", progress = "Es ist nicht leicht, alten Freunden Frieden zu schenken.", completion = "Das sollte den Angriff für eine Weile durcheinanderbringen, doch wir müssen der Sache auf den Grund gehen. Diese Anführer waren von einer Art teuflischer Verderbtheit durchdrungen, meint Ihr nicht?", sourceObjectiveStatus = "unverified-source-field" }
quests[46107] = { id = 46107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Quelle der Verderbnis", description = "Mit den dreien stimmte etwas nicht. Sie hatten eine teuflische Verderbtheit an sich, die... verstörend war. Ich glaube, sie wurden irgendwie später erweckt als die anderen Auferstandenen. Diese verdammte Legion mit ihren widerwärtigen Experimenten!\n\nDie Verstärkungen, die aus der Rabenwehr strömen, kommen von der Heldenrast. Wir müssen dorthin und versuchen, die Quelle dieser neuen Truppen zum Versiegen zu bringen.", sourceObjective = "Findet die Quelle der Verderbnis an der Heldenrast und bereitet ihr ein Ende.", progress = "Wir müssen dieser Verderbnis ein Ende setzen.", completion = "Die Angriffe auf Bradenbach sollten jetzt nachlassen. Wir müssen uns immer noch um Lord Erdris kümmern, und zwar bald.", sourceObjectiveStatus = "unverified-source-field" }
quests[46108] = { id = 46108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissen ist Artefaktmacht", description = "Während unseres gesamten Feldzugs auf den Verheerten Inseln habt Ihr die Macht Eures Artefakts stetig gesteigert. Aber angesichts dessen, dass die Invasion der Legion an Intensität gewonnen hat, ist es wichtiger denn je, dass wir mehr über das Potenzial Eurer Waffe erfahren.\n\nStetiger und langsamer Fortschritt hat seine Vorzüge, doch nun ist es an der Zeit, dass wir rascher zu Ergebnissen kommen.\n\nIndem wir die Ressourcen unseres Ordens in den Dienst der Erforschung der Geschichte dieser Waffe stellen, können wir, so glaube ich, die Rate, mit der das Artefakt an Macht gewinnt, drastisch erhöhen.\n\nWas meint Ihr? Sollen wir beginnen, {class}t?", sourceObjective = "Stellt Ordensressourcen zur Verfügung, um Artefaktwissen zu enthüllen.", progress = "Der Einsatz der von unserem Orden gesammelten Ressourcen wird uns schnelle Fortschritte ermöglichen.", completion = "Wenn wir mehr über Euer Artefakt herausfinden können, wird uns das in unserem Kampf gegen die Legion sicherlich von Nutzen sein.\n\nSofern Ihr mir Ordensressourcen zur Verfügung stellt, kann ich Euch mit Notizen über die Forschungsergebnisse hinsichtlich Eurer Waffe versorgen. Lest Euch ruhig ein, vielleicht habt Ihr dann ein besseres Verständnis von der Macht, mit der Ihr Euer Artefakt ausstatten könnt.\n\nTod unseren Feinden!", sourceObjectiveStatus = "unverified-source-field" }
quests[46109] = { id = 46109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erhebt Euch!" }
quests[46110] = { id = 46110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht um Sturmheim", description = "Durch Eure Anstrengungen wurden die Legionsstreitkräfte auf der Schildruhinsel vernichtet... und doch greifen sie weiterhin an.\n\nEs gibt nur eine Möglichkeit, dem ein Ende zu setzen. Ihr müsst Euch mitten unter unsere Feinde begeben, ihren Kommandanten finden und seinen widerlichen Kopf abschlagen!", sourceObjective = "Besiegt Lordkommandant Alexius in Sturmheim.", completion = "Gut gemacht, {name}! Wirklich sehr gut gemacht!\n\nDie Legion wird den Tag bereuen, an dem sie sich Sturmheim zum Ziel erkoren hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[46111] = { id = 46111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illidarimeister: Sissix" }
quests[46112] = { id = 46112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illidarimeister: Madame Viciosa" }
quests[46113] = { id = 46113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illidarimeister: Namenloser Mystiker" }
quests[46116] = { id = 46116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf unheiligem Boden" }
quests[46119] = { id = 46119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Segen des Konstrukteurs", sourceObjective = "{name}! Hört mal her, Ihr habt unser Geschäft richtig belebt, und ich meine so RICHTIG. Hätte niemals gedacht, dass ich mal derartig viele Knarren verkaufen würde.\n\nUnd wir belohnen diejenigen gern, die unsere Geschäfte vorantreiben, also... hier. Nehmt dies.\n\nKlatscht das Teil einfach auf Eure Schulterpolster und geht auf die Jagd nach Ingenieurszubehör. Ihr werdet überrascht sein, bei wie vielen Basilisken Ihr Zahnkränze zwischen den Zähnen finden könnt!", sourceObjectiveStatus = "unverified-source-field" }
quests[46125] = { id = 46125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiterbildung", description = "Es ist unglaublich, wie viel wir bereits über diese Artefakte in Erfahrung bringen konnten.\n\nUnsere Forscher waren damit beschäftigt, die entsprechenden Unterlagen für Euch vorzubereiten. Und ich bin mir sicher, dass wir nur mit ein paar mehr Ressourcen einen Einführungskurs zusammenstellen können, mit dem sich Euer Artefaktwissen erweitern lässt.\n\nDas ist aber nur der erste Schritt, denn mit mehr Ressourcen können wir weitere Kurse vorbereiten, die Euch bei Euren Studien unterstützen können.", sourceObjective = "Liefert genug Ordensressourcen ab, um einen Einführungskurs in Artefaktwissen abzuschließen.", progress = "Wenn Ihr mir mehr Ressourcen bringt, kann ich weitere Berichte über die Geschichte und das Potenzial Eurer Artefaktwaffe anfertigen.\n\nDieses Wissen braucht Ihr, um Eurer Waffe zusätzliche Macht zu verleihen.\n\nBringt mir diese Ressourcen so bald Ihr könnt. Die Legion muss fallen!", completion = "Die Ordensressourcen, die Ihr gebracht habt, sind unabdingbar, wenn Ihr Eure Waffe weiter verstärken wollt.\n\nNehmt diese Notizen. Lest Euch die Forschungsberichte durch und wendet das gelernte Wissen an.\n\nVorwärts zum Sieg!", sourceObjectiveStatus = "unverified-source-field" }
quests[46126] = { id = 46126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsverderbte Federn" }
quests[46127] = { id = 46127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwillinge bezwingen", description = "Ich habe Neuigkeiten von Erzmagier Karlain! Die Kirin Tor haben Raest Magusspeer ausfindig gemacht und können ein Portal zu seinem Aufenthaltsort öffnen!\n\nWenn Ihr bereit seid, ihm gegenüberzutreten, werde ich die hiesigen Magier anweisen, das Portal in den Wirbelnden Nether zu öffnen.", sourceObjective = "Sprecht mit Kriegsrätin Victoria, um Euch zu Raests Aufenthaltsort teleportieren zu lassen und ihn zu besiegen.", completion = "Dann ist Raest also gefallen und hat in seinem Größenwahn auch noch seinen Bruder mit in den Tod gerissen. Ich trauere um beide, doch insbesondere der Tod seines Bruders ist bedauerlich.\n\nKaram Magusspeer war ein wahres Leuchtfeuer des Lichts. Ich kann nur hoffen, dass die Geschichte seines Opfers die Zeit überdauert. \n\nIhr habt gute Arbeit geleistet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[46128] = { id = 46128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit zum Aufladen", sourceObjective = "Ich hab mir nochmal ein paar Gedanken über die Sache mit den Batterien gemacht. Der ganze Prozess ist einfach nicht... nachhaltig.\n\nKeine Bange, mir ist die Umwelt immer noch latte, ich mach' mir einfach nur sorgen um meinen Profit!\n\nWenn ich nur jemanden finden könnte, der eine dieser Batterien mit etwas Blut von Sargeras auflädt und den Prozess mit konzentriertem Leystein abrundet...", sourceObjectiveStatus = "unverified-source-field" }
quests[46129] = { id = 46129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissen ist Artefaktmacht", description = "Chef, ich weiß, Ihr seid mehrmals quer über die Verheerten Inseln gelatscht, um dieses uralte Artefakt zu verstärken. Aber diese Dämonen wollen einfach nicht aufgeben und deshalb müssen wir herausfinden, wie wir der Waffe einen größeren Teil ihres Potenzials entlocken können... und zwar pronto!\n\nLangsamer und stetiger Fortschritt ist zwar schön und gut, aber jetzt müssen wir uns ranhalten.\n\nAlso Folgendes: Ihr macht unsere Ordensressourcen locker, damit wir die Vergangenheit dieser Waffe entschlüsseln können, und wir finden einen Weg, wie Ihr das Artefakt mit deutlich mehr Macht ausstatten könnt.\n\nWas sagt Ihr dazu, {class}t?", sourceObjective = "Stellt Ordensressourcen zur Verfügung, um Artefaktwissen zu enthüllen.", progress = "Das wird sich richtig lohnen, Chef! Der Einsatz der von unserem Orden gesammelten Ressourcen wird uns ordentlich nach vorne bringen.", completion = "Hey Chef, je mehr wir über Euer Artefakt herausfinden können, desto eher können wir den Sieg über die Legion feiern.\n\nWenn Ihr mir Ordensressourcen zur Verfügung stellt, kann ich Euch ein paar Notizen über die Forschungsergebnisse zu Eurer Waffe zusammenkritzeln lassen. Die könnt Ihr Euch dann durchlesen, um mehr über die Macht zu lernen, mit der Ihr Euer Artefakt ausstatten könnt.\n\nAlso worauf warten wir noch?!", sourceObjectiveStatus = "unverified-source-field" }
quests[46130] = { id = 46130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissen ist Artefaktmacht", description = "Während unseres gesamten Feldzugs auf den Verheerten Inseln habt Ihr die Macht Eures Artefakts stetig gesteigert. Aber angesichts dessen, dass die Invasion der Legion an Intensität gewonnen hat, ist es wichtiger denn je, dass wir mehr über das Potenzial Eurer Waffe erfahren.\n\nStetiger und langsamer Fortschritt hat seine Vorzüge, doch nun ist es an der Zeit, dass wir rascher zu Ergebnissen kommen.\n\nIndem wir die Ressourcen unseres Ordens in den Dienst der Erforschung der Geschichte dieser Waffe stellen, können wir, so glaube ich, die Rate, mit der das Artefakt an Macht gewinnt, drastisch erhöhen.\n\nWas meint Ihr? Sollen wir beginnen, {class}t?", sourceObjective = "Stellt Ordensressourcen zur Verfügung, um Artefaktwissen zu enthüllen.", progress = "Der Einsatz der von unserem Orden gesammelten Ressourcen wird uns schnelle Fortschritte ermöglichen.", completion = "Wenn wir mehr über Euer Artefakt herausfinden können, wird uns das in unserem Kampf gegen die Legion sicherlich von Nutzen sein.\n\nSofern Ihr mir Ordensressourcen zur Verfügung stellt, kann ich Euch mit Notizen über die Forschungsergebnisse hinsichtlich Eurer Waffe versorgen. Lest Euch ruhig ein, vielleicht habt Ihr dann ein besseres Verständnis von der Macht, mit der Ihr Euer Artefakt ausstatten könnt.\n\nFür Azeroth!", sourceObjectiveStatus = "unverified-source-field" }
quests[46131] = { id = 46131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissen ist Artefaktmacht", description = "Ihr seid wahrlich die Geißel der Verheerten Inseln. Es ist herrlich, mitanzusehen, wie Ihr unseren Feinden ihre Macht entreißt und damit Euer uraltes Artefakt verstärkt. Aber wir sollten uns nicht darauf ausruhen! Lasst uns das tief verborgen liegende Potenzial Eurer Waffe freisetzen.\n\nDie Zeit für langsamen und stetigen Fortschritt war gestern. Heute werden wir unsere Anstrengungen verdoppeln.\n\nIch glaube, indem wir unsere Ordensressourcen dem Studium der Geschichte des Artefakts widmen, sollten wir das Maß an Macht ausbauen können, mit der Ihr Euer Artefakt ausstatten könnt. Und Macht ist, wie Ihr ja wisst, geradezu berauschend.\n\nSollen wir beginnen, {class}t?", sourceObjective = "Stellt Ordensressourcen zur Verfügung, um Artefaktwissen zu enthüllen.", progress = "Der Einsatz der von unserem Orden gesammelten Ressourcen wird uns dabei helfen, schnelle Fortschritte bei der Verstärkung Eures Artefakts und der Unterjochung unsere Feinde zu erzielen.", completion = "Das Wissen über Euer Artefakt ist der Schlüssel zur Unterjochung der Dämonen.\n\nWenn Ihr mir genug Ordensressourcen liefert, kann ich Euch Notizen über den derzeitigen Stand der Forschung zukommen lassen. Lest sie, prägt sie Euch ein, Netherfürst, und Ihr werdet verstehen, wie Ihr die Macht vergrößern könnt, mit der Ihr Artefakt ausstattet.\n\nEure Feinde werden vor Euch erzittern... ganz so, wie es sein sollte!", sourceObjectiveStatus = "unverified-source-field" }
quests[46132] = { id = 46132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissen ist Artefaktmacht", description = "Während unseres Feldzugs auf den Verheerten Inseln habt Ihr Eurem uralten Artefakt immer wieder zusätzliche Macht verliehen. Aber die Invasion der Legion hat ihren Höhepunkt noch nicht erreicht. Wir müssen also Eurer Waffe noch mehr ihres Potenzials entlocken.\n\nIch mag langsamen und stetigen Fortschritt. Aber das ist jetzt nicht gefragt. Wir müssen unsere Anstrengungen beschleunigen.\n\nIndem wir die Ressourcen unseres Ordens dazu einsetzen, die Geschichte der Waffe zu studieren, können wir die Macht dramatisch erhöhen, die Ihr Eurem Artefakt zuführen könnt.\n\nDaher sollten wir am besten sofort anfangen, {class}t!", sourceObjective = "Stellt Ordensressourcen zur Verfügung, um Artefaktwissen zu enthüllen.", progress = "Mithilfe der von unserem Orden gesammelten Ressourcen werden wir sicher schnelle Fortschritte bei der Erforschung dieser Waffe erzielen.", completion = "Alles, was wir über Euer Artefakt in Erfahrung bringen können, wird uns dabei helfen, die Legion zu besiegen.\n\nSofern Ihr mir Ordensressourcen zur Verfügung stellt, kann ich Euch mit Notizen über die Forschungsergebnisse hinsichtlich Eurer Waffe versorgen. Lest sie, und erfahrt mehr über die Macht, mit der Ihr Euer Artefakt ausstatten könnt.\n\nFür Azeroth!", sourceObjectiveStatus = "unverified-source-field" }
quests[46133] = { id = 46133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissen ist Artefaktmacht", description = "Während unseres Feldzugs auf den Verheerten Inseln habt Ihr eine Schneise in die Reihen unserer Feinde geschlagen und Euer uraltes Artefakt beständig mit neuer Macht verstärkt. Aber die Legion treibt ihre Invasion heftiger denn je voran und daher ist es jetzt umso wichtiger, dass wir schnell einen größeren Teil des Potentials Eurer Waffe entfalten.\n\nDie Zeit des langsamen und stetigen Fortschritts ist vorbei. Nun zählen nur rasche Erfolge.\n\nMit unseren Ordensressourcen könnten wir, so glaube ich, die Geheimnisse der Waffe schneller entdecken und die Macht erhöhen, die Ihr Eurem Artefakt zuführen könnt.\n\nSollen wir beginnen, {class}t?", sourceObjective = "Stellt Ordensressourcen zur Verfügung, um Artefaktwissen zu enthüllen.", progress = "Der Einsatz der von unserem Orden gesammelten Ressourcen wird uns schnelle Fortschritte ermöglichen.", completion = "Wenn wir mehr über Euer Artefakt herausfinden können, wird uns das in unserem Kampf gegen die Legion sicherlich von Nutzen sein.\n\nSofern Ihr mir Ordensressourcen zur Verfügung stellt, kann ich Euch mit Notizen über die Forschungsergebnisse hinsichtlich Eurer Waffe versorgen. Lest Euch ruhig ein, vielleicht habt Ihr dann ein besseres Verständnis von der Macht, mit der Ihr Euer Artefakt ausstatten könnt.\n\nSollen Schmerz und Elend unsere Feinde verschlingen!", sourceObjectiveStatus = "unverified-source-field" }
quests[46134] = { id = 46134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Juwelenschleifer gesucht" }
