quests[46140] = { id = 46140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissen ist Artefaktmacht", description = "Während unseres gesamten Feldzugs auf den Verheerten Inseln habt Ihr die Macht Eures Artefakts stetig gesteigert. Aber angesichts dessen, dass die Invasion der Legion an Intensität gewonnen hat, ist es wichtiger denn je, dass wir mehr über das Potenzial Eurer Waffe erfahren.\n\nStetiger und langsamer Fortschritt hat seine Vorzüge, doch nun ist es an der Zeit, dass wir rascher zu Ergebnissen kommen.\n\nIndem wir die Ressourcen unseres Ordens in den Dienst der Erforschung der Geschichte dieser Waffe stellen, können wir, so glaube ich, die Rate, mit der das Artefakt an Macht gewinnt, drastisch erhöhen.\n\nDie Schatten verdichten sich, {class}t. Fangen wir an.", sourceObjective = "Stellt Ordensressourcen zur Verfügung, um Artefaktwissen zu enthüllen.", progress = "Der Einsatz der von unserem Orden gesammelten Ressourcen wird uns schnelle Fortschritte ermöglichen.", completion = "Wenn wir mehr über Euer Artefakt herausfinden können, wird uns das unserem Sieg über die Legion einen Schritt näher bringen.\n\nSofern Ihr mir Ordensressourcen zur Verfügung stellt, kann ich Euch mit Notizen über die Forschungsergebnisse hinsichtlich Eurer Waffe versorgen. Lest Euch ruhig ein, vielleicht habt Ihr dann ein besseres Verständnis von der Macht, mit der Ihr Euer Artefakt ausstatten könnt.\n\nWir werden die Legion zurück in die Hölle treiben, aus der sie gekommen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[46141] = { id = 46141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissen ist Artefaktmacht", description = "Während unseres gesamten Feldzugs auf den Verheerten Inseln habt Ihr die Macht Eures Artefakts stetig gesteigert. Aber angesichts dessen, dass die Invasion der Legion an Intensität gewonnen hat, ist es wichtiger denn je, dass wir mehr über das Potenzial Eurer Waffe erfahren.\n\nStetiger und langsamer Fortschritt hat seine Vorzüge, doch nun ist es an der Zeit, dass wir rascher zu Ergebnissen kommen.\n\nIndem wir die Ressourcen unseres Ordens in den Dienst der Erforschung der Geschichte dieser Waffe stellen, können wir, so glaube ich, die Rate, mit der das Artefakt an Macht gewinnt, drastisch erhöhen.\n\nWas meint Ihr? Sollen wir beginnen, {class}t?", sourceObjective = "Stellt Ordensressourcen zur Verfügung, um Artefaktwissen zu enthüllen.", progress = "Der Einsatz der von unserem Orden gesammelten Ressourcen wird uns schnelle Fortschritte ermöglichen.", completion = "Wenn wir mehr über Euer Artefakt herausfinden können, wird uns das in unserem Kampf gegen die Legion sicherlich von Nutzen sein.\n\nSofern Ihr mir Ordensressourcen zur Verfügung stellt, kann ich Euch mit Notizen über die Forschungsergebnisse hinsichtlich Eurer Waffe versorgen. Lest Euch ruhig ein, vielleicht habt Ihr dann ein besseres Verständnis von der Macht, mit der Ihr Euer Artefakt ausstatten könnt.\n\nFür Azeroth!", sourceObjectiveStatus = "unverified-source-field" }
quests[46142] = { id = 46142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissen ist Artefaktmacht", description = "Feind um Feind habt Ihr auf den Verheerten Inseln in den Boden gestampft und Eurem Artefakt große Kraft verliehen, aber die Legion kämpft ohne Ehre. Um sie zu besiegen, müssen wir das ganze Potenzial Eurer Waffe offenlegen.\n\nLangsame und stetige Fortschritte müssen warten. Jetzt gilt es, so schnell wie möglich den Weg zum Sieg zu ebnen.\n\nWenn wir unsere Ordensressourcen dazu einsetzen, die Vergangenheit der Waffe zu erforschen, werden wir meines Erachtens Wege finden können, die Macht zu steigern, mit der Ihr Eure Waffe verstärken könnt.\n\nDer Ruhm erwartet uns, {class}t!", sourceObjective = "Stellt Ordensressourcen zur Verfügung, um Artefaktwissen zu enthüllen.", progress = "Der Einsatz der von unserem Orden gesammelten Ressourcen wird uns schnelle Fortschritte ermöglichen. Unsere Feinde werden vor uns erzittern!", completion = "Die Macht alter Legenden ist nicht zu unterschätzen. Die Entschlüsselung der Vergangenheit Eures Artefakts wird unseren Sieg über die Legion befördern.\n\nWenn Ihr mir noch mehr Ordensressourcen bringt, kann ich Euch Geschichten niederschreiben, die Euch in Erstaunen versetzen. Lest und die Kraft, mit der Ihr Euer Artefakt verstärkt, wird in den Hallen der Tapferkeit widerhallen.\n\nFür Odyn!", sourceObjectiveStatus = "unverified-source-field" }
quests[46143] = { id = 46143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissen ist Artefaktmacht", description = "Während unseres gesamten Feldzugs auf den Verheerten Inseln habt Ihr die Macht Eures Artefakts stetig gesteigert. Aber angesichts dessen, dass die Invasion der Legion an Intensität gewonnen hat, ist es wichtiger denn je, dass wir mehr über das Potenzial Eurer Waffe erfahren.\n\nStetiger und langsamer Fortschritt hat seine Vorzüge, doch nun ist es an der Zeit, dass wir rascher zu Ergebnissen kommen.\n\nIndem wir die Ressourcen unseres Ordens in den Dienst der Erforschung der Geschichte dieser Waffe stellen, können wir, so glaube ich, die Rate, mit der das Artefakt an Macht gewinnt, drastisch erhöhen.\n\nWas meint Ihr? Sollen wir beginnen, {class}t?", sourceObjective = "Stellt Ordensressourcen zur Verfügung, um Artefaktwissen zu enthüllen.", progress = "Der Einsatz der von unserem Orden gesammelten Ressourcen wird uns schnelle Fortschritte ermöglichen.", completion = "Wenn wir mehr über Euer Artefakt herausfinden können, wird uns das in unserem Kampf gegen die Legion sicherlich von Nutzen sein.\n\nSofern Ihr mir Ordensressourcen zur Verfügung stellt, kann ich Euch mit Notizen über die Forschungsergebnisse hinsichtlich Eurer Waffe versorgen. Lest Euch ruhig ein, vielleicht habt Ihr dann ein besseres Verständnis von der Macht, mit der Ihr Euer Artefakt ausstatten könnt.\n\nFür Azeroth!", sourceObjectiveStatus = "unverified-source-field" }
quests[46144] = { id = 46144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissen ist Artefaktmacht", description = "Während unseres gesamten Feldzugs auf den Verheerten Inseln habt Ihr die Macht Eures Artefakts stetig gesteigert. Aber angesichts dessen, dass die Invasion der Legion an Intensität gewonnen hat, ist es wichtiger denn je, dass wir mehr über das Potenzial Eurer Waffe erfahren.\n\nStetiger und langsamer Fortschritt hat seine Vorzüge, doch nun ist es an der Zeit, dass wir rascher zu Ergebnissen kommen.\n\nIndem wir die Ressourcen unseres Ordens in den Dienst der Erforschung der Geschichte dieser Waffe stellen, können wir, so glaube ich, die Rate, mit der das Artefakt an Macht gewinnt, drastisch erhöhen.\n\nWollen wir seine Geschichte entdecken, {class}t?", sourceObjective = "Stellt Ordensressourcen zur Verfügung, um Artefaktwissen zu enthüllen.", progress = "Der Einsatz der von unserem Orden gesammelten Ressourcen wird uns schnelle Fortschritte ermöglichen.", completion = "Wenn wir mehr über Euer Artefakt herausfinden können, wird uns das in unserem Kampf gegen die Legion sicherlich von Nutzen sein.\n\nSofern Ihr mir Ordensressourcen zur Verfügung stellt, kann ich Euch mit Notizen über die Forschungsergebnisse hinsichtlich Eurer Waffe versorgen. Vertieft Euch in diese Geschichten, denn aus ihnen werdet Ihr lernen, wie Ihr die Macht, mit der Ihr Euer Artefakt ausstatten könnt, besser nutzt.\n\nAus Geschichten schöpfen wir Kraft!", sourceObjectiveStatus = "unverified-source-field" }
quests[46145] = { id = 46145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sterile Umgebung", description = "Da die Gefahr der Infektion beseitigt wurde, können Eure Verbündeten nun ihren Angriff an der Verheerten Küste fortsetzen und sich einen Vorteil gegenüber der Brennenden Legion erarbeiten.\n\nLasst uns aufbrechen und an einem... sterileren Ort weiterreden. Ich habe gehört, Euer Orden besitzt einen beeindruckenden Tempel.", sourceObjective = "Kehrt zum Netherlichttempel zurück.", completion = "Was für ein reizender Ort. Sehr viel gastfreundlicher als diese dämonenverseuchte Insel.", sourceObjectiveStatus = "unverified-source-field" }
quests[46146] = { id = 46146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die brennenden Ufer" }
quests[46147] = { id = 46147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissen ist Artefaktmacht", description = "Während unseres gesamten Feldzugs auf den Verheerten Inseln habt Ihr die Macht Eures Artefakts stetig gesteigert. Aber angesichts dessen, dass die Invasion der Legion an Intensität gewonnen hat, ist es wichtiger denn je, dass wir mehr über das Potenzial Eurer Waffe erfahren.\n\nStetiger und langsamer Fortschritt hat seine Vorzüge, doch heute müssen wir mir der Eile des Windes vorgehen.\n\nIndem wir die Ressourcen unseres Ordens in den Dienst der Erforschung der Geschichte dieser Waffe stellen, können wir, so glaube ich, die Rate, mit der das Artefakt an Macht gewinnt, drastisch erhöhen.\n\nWas meint Ihr? Sollen wir beginnen, {class}t?", sourceObjective = "Stellt Ordensressourcen zur Verfügung, um Artefaktwissen zu enthüllen.", progress = "Ich glaube, der Einsatz der von unserem Orden gesammelten Ressourcen wird uns schnelle Fortschritte ermöglichen.", completion = "Wenn wir mehr über Euer Artefakt herausfinden können, wird uns das schneller auf unserem Pfad zum Sieg über die Legion voranbringen.\n\nSofern Ihr mir Ordensressourcen zur Verfügung stellt, kann ich Euch mit Notizen über die Forschungsergebnisse hinsichtlich Eurer Waffe versorgen. Lest Euch ruhig ein, vielleicht habt Ihr dann ein besseres Verständnis von der Macht, mit der Ihr Euer Artefakt ausstatten könnt.\n\nMögen die Winde Euch leiten!", sourceObjectiveStatus = "unverified-source-field" }
quests[46148] = { id = 46148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiterbildung", description = "Wir wissen jetzt schon ein bisschen mehr über die Macht des Artefakts und ich untersuche gerade, wie wir davon profitieren können.\n\nWir haben ein Gruppe Schreiberlinge dazu genötigt, das alles mal schriftlich festzuhalten, doch sie benötigen angeblich noch mehr Ressourcen, bevor sie das endgültige Produkt liefern können.\n\nDie gute Nachricht ist, dass wir sicherlich noch ein paar mehr Kurse aus ihnen herauspressen können. Aber danach müssen wir leider wieder selbst die Ärmel hochkrempeln.", sourceObjective = "Liefert genug Ordensressourcen ab, um einen Einführungskurs in Artefaktwissen abzuschließen.", progress = "Hey, wisst Ihr was? Wenn Ihr mir noch mehr Ordensressourcen zusteckt, kann ich Euch bestimmt zusätzliche Notizen über die Geschichte und das Potenzial des Artefakts besorgen.\n\nIhr müsst Eure Waffe verstärken und ich kann Euch das nötige Wissen beschaffen, was Ihr dafür braucht.\n\nBringt mir die Ressourcen, aber so schnell Ihr könnt. Vorher läuft hier nämlich gar nichts!", completion = "Diese Ordensressourcen sind Euer Fahrschein zur absoluten Artefaktmacht.\n\nHier, nehmt diese Notizen. Ich selbst hab's eigentlich nicht so mit dem Lesen, aber in diesem Fall sollte man sich ruhig die Zeit nehmen. Euer Artefakt wird uns noch allen den Hintern retten.\n\nViel Glück, Chef!", sourceObjectiveStatus = "unverified-source-field" }
quests[46149] = { id = 46149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiterbildung", description = "Was wir bisher in Erfahrung bringen konnten, ist erstaunlich. Ich denke, ich kann unsere ersten Erkenntnisse für Euch in Form von Notizen aufbereiten, damit Ihr Euch schnell einlesen könnt.\n\nWir brauchen nur noch ein paar mehr Ressourcen, um die Notizen ordentlich aufbereiten zu können.\n\nDie Anstrengungen, die wir jetzt unternehmen, sollten unser Wissen beträchtlich erweitern und uns noch tiefere Einblicke in das verborgene Potenzial dieser Waffen gewähren.", sourceObjective = "Liefert genug Ordensressourcen ab, um einen Einführungskurs in Artefaktwissen abzuschließen.", progress = "Wenn Ihr mir mehr Ressourcen bringt, kann ich weitere Berichte über die Geschichte und das Potenzial Eurer Artefaktwaffe anfertigen.\n\nDieses Wissen braucht Ihr, um Eurer Waffe zusätzliche Macht zu verleihen.\n\nBringt mir diese Ressourcen so bald Ihr könnt. Die Legion muss fallen!", completion = "Die Ordensressourcen, die Ihr gebracht habt, sind unabdingbar, wenn Ihr Eure Waffe weiter verstärken wollt.\n\nNehmt diese Notizen. Lest Euch die Forschungsberichte durch und wendet das gelernte Wissen an.\n\nVorwärts zum Sieg!", sourceObjectiveStatus = "unverified-source-field" }
quests[46150] = { id = 46150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiterbildung", description = "Die Macht, die in diesen Artefakten steckt, ist unglaublich, und wir haben bisher nur an der Oberfläche gekratzt.\n\nUnsere Forscher waren damit beschäftigt, die entsprechenden Erkenntnisse für Euch aufzubereiten. Und ich bin mir sicher, dass wir mit ein paar mehr Ressourcen auch Informationsmaterial für Euch zusammenstellen können, mit dem Ihr Euer Artefaktwissen vermehren könnt.\n\nDas ist aber nur der erste Schritt, denn mit mehr Ressourcen können wir Euch noch viel tiefer in die Forschung eintauchen lassen.", sourceObjective = "Liefert genug Ordensressourcen ab, um einen Einführungskurs in Artefaktwissen abzuschließen.", progress = "Wenn Ihr mir mehr Ressourcen bringt, kann ich weitere Berichte über die Geschichte und das Potenzial Eurer Artefaktwaffe anfertigen.\n\nDieses Wissen braucht Ihr, um Eurer Waffe zusätzliche Macht zu verleihen.\n\nBringt mir diese Ressourcen so bald Ihr könnt. Unser Sieg wartet!", completion = "Die Ordensressourcen, die Ihr gebracht habt, sind unabdingbar, wenn Ihr Eure Waffe weiter verstärken wollt.\n\nNehmt diese Notizen. Lasst Euch in die dunklen Geheimnisse darin einweihen und wendet das gelernte Wissen an.\n\nAll unsere Feinde werden vor uns fallen!", sourceObjectiveStatus = "unverified-source-field" }
quests[46151] = { id = 46151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiterbildung", description = "Jeder Tag, den ich mit den Studien der Geschichte dieser Waffen zubringe, birgt Überraschungen und fördert Erstaunliches zutage.\n\nUnsere Forschung geht außerordentlich gut voran und wir waren ohne Unterlass damit beschäftigt, die entsprechenden Notizen für Euch aufzubereiten. Mit ein paar mehr Ressourcen können wir unser Artefaktwissen sicherlich noch deutlich vermehren.\n\nDenkt aber daran, dass dies nur der erste Schritt ist, denn diese Waffen sind älter als alle uns bekannten Aufzeichnungen. Daher werden tiefere Erkenntnisse uns auch mehr Zeit kosten.", sourceObjective = "Liefert genug Ordensressourcen ab, um einen Einführungskurs in Artefaktwissen abzuschließen.", progress = "Mit noch mehr Ressourcen kann ich Euch weitere Notizen über die Herkunft, Geschichte und das Potenzial Eurer Artefaktwaffe aufschreiben.\n\n Dieses Wissen wird uns entscheidend dabei helfen, Eure Waffe mit mehr Macht auszustatten.\n\nBringt mir die Ressourcen, sobald Ihr könnt. Die Legion muss fallen!", completion = "Die Ordensressourcen, die Ihr gebracht habt, sind unerlässlich, wenn Ihr Eure Waffe weiter verstärken wollt.\n\nNehmt diese Notizen. Lest Euch die Forschungsberichte durch und wendet das gelernte Wissen an.\n\nVorwärts zum Sieg!", sourceObjectiveStatus = "unverified-source-field" }
quests[46152] = { id = 46152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiterbildung", description = "Es hat uns einiges an Blut und Schweiß gekostet, aber wir haben unsere ersten Forschungen abgeschlossen.\n\nWir waren unermüdlich damit beschäftigt, die entsprechenden Erkenntnisse für Euch aufzubereiten. Und ich bin mir sicher, dass wir mit ein paar mehr Ressourcen auch Informationsmaterial für Euch zusammenstellen können, mit dem Ihr Euer Artefaktwissen vermehren könnt.\n\nDas ist nur ein erster Schritt. Wenn Ihr tiefer in die Materie eindringen wollt, benötigen wir mehr Ressourcen.", sourceObjective = "Liefert genug Ordensressourcen ab, um einen Einführungskurs in Artefaktwissen abzuschließen.", progress = "Wenn Ihr mir mehr Ressourcen bringt, kann ich weitere Berichte über die Geschichte und das Potenzial Eurer Artefaktwaffe anfertigen.\n\nDieses Wissen braucht Ihr, um Eurer Waffe zusätzliche Macht zu verleihen.\n\nBringt mir diese Ressourcen so bald Ihr könnt und die Legion wird leiden!", completion = "Die Ordensressourcen, die Ihr gebracht habt, sind unabdingbar, wenn Ihr Eure Waffe weiter verstärken wollt.\n\nNehmt diese Notizen. Lest Euch die Forschungsberichte durch und wendet das gelernte Wissen an.\n\nVorwärts zum Sieg!", sourceObjectiveStatus = "unverified-source-field" }
quests[46153] = { id = 46153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiterbildung", description = "Die Macht, die in diesen Artefakten steckt, ist unglaublich, und wir haben bisher nur an der Oberfläche gekratzt.\n\nUnsere Forscher waren damit beschäftigt, die entsprechenden Erkenntnisse für Euch aufzubereiten. Und ich bin mir sicher, dass wir mit ein paar mehr Ressourcen auch Informationsmaterial für Euch zusammenstellen können, mit dem Ihr Euer Artefaktwissen vermehren könnt.\n\nDas ist aber nur der erste Schritt, denn mit mehr Ressourcen können wir Euch noch viel tiefer in die Forschung eintauchen lassen.", sourceObjective = "Liefert genug Ordensressourcen ab, um einen Einführungskurs in Artefaktwissen abzuschließen.", progress = "Wenn Ihr mir mehr Ressourcen bringt, kann ich weitere Berichte über die Geschichte und das Potenzial Eurer Artefaktwaffe anfertigen.\n\nDieses Wissen braucht Ihr, um Eurer Waffe zusätzliche Macht zu verleihen.\n\nBringt mir diese Ressourcen so bald Ihr könnt. Die Legion wird fallen!", completion = "Die Ordensressourcen, die Ihr gebracht habt, sind unabdingbar, wenn Ihr Eure Waffe weiter verstärken wollt.\n\nNehmt diese Notizen. Lest Euch die Forschungsberichte durch und wendet das gelernte Wissen an.\n\nDer Sieg wird uns gehören!", sourceObjectiveStatus = "unverified-source-field" }
quests[46154] = { id = 46154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiterbildung", description = "Die Macht, die in diesen Artefakten steckt, ist unglaublich, und wir haben bisher nur an der Oberfläche gekratzt.\n\nUnsere Forscher waren damit beschäftigt, die entsprechenden Erkenntnisse für Euch aufzubereiten. Und ich bin mir sicher, dass wir mit ein paar mehr Ressourcen auch Informationsmaterial für Euch zusammenstellen können, mit dem Ihr Euer Artefaktwissen vermehren könnt.\n\nDas ist aber nur der erste Schritt, denn mit mehr Ressourcen können wir Euch noch viel tiefer in die Forschung eintauchen lassen.", sourceObjective = "Liefert genug Ordensressourcen ab, um einen Einführungskurs in Artefaktwissen abzuschließen.", progress = "Wenn Ihr mir mehr Ressourcen bringt, kann ich weitere Berichte über die Geschichte und das Potenzial Eurer Artefaktwaffe anfertigen.\n\nDieses Wissen braucht Ihr, um Eurer Waffe zusätzliche Macht zu verleihen.\n\nBringt mir diese Ressourcen so bald Ihr könnt. Wir müssen das Gleichgewicht wiederherstellen!", completion = "Die Ordensressourcen, die Ihr gebracht habt, sind unabdingbar, wenn Ihr Eure Waffe weiter verstärken wollt.\n\nNehmt diese Notizen. Lest Euch die Forschungsberichte durch und wendet das gelernte Wissen an.\n\nVorwärts zum Sieg!", sourceObjectiveStatus = "unverified-source-field" }
quests[46155] = { id = 46155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiterbildung", description = "Die Erforschung dieser uralten Magien und Metalle hat uns tiefe Einblicke in das Potenzial dieser Waffen gewährt.\n\nDas Schmieden dieser Waffen brauchte eine lange Zeit und erforderte große Mühen. Es wird uns zwar ebenso einiges abverlangen, Euch eine Anleitung zur Handhabung und Verstärkung Eures Artefakts herzustellen, aber ich denke, mit ein paar zusätzlichen Ordensressourcen werden wir Euch eine Einleitung geben können, mit der Ihr Euer Wissen erweitern könnt.\n\nUnd das ist der erst Anfang dessen, was uns noch erwartet, wenn wir tiefer in das verlorene Wissen eindringen. Aber das wird Zeit kosten.", sourceObjective = "Liefert genug Ordensressourcen ab, um einen Einführungskurs in Artefaktwissen abzuschließen.", progress = "Wenn Ihr mir mehr Ressourcen bringt, kann ich weitere Berichte über die Geschichte und das Potenzial Eurer Artefaktwaffe anfertigen.\n\nDieses Wissen braucht Ihr, um Eurer Waffe zusätzliche Macht zu verleihen.\n\nBringt mir diese Ressourcen sobald Ihr könnt. Für die Valarjar!", completion = "Die Ordensressourcen, die Ihr gebracht habt, sind unabdingbar, wenn Ihr Eure Waffe weiter verstärken wollt.\n\nNehmt diese Notizen. Lest Euch die Geschichten darin durch und wendet das gelernte Wissen an.\n\nLasst die Sänger von unseren Taten dichten!", sourceObjectiveStatus = "unverified-source-field" }
quests[46156] = { id = 46156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiterbildung", description = "<Werter Herr/Werte Dame> ich schulde Euch und der Tirisgarde meinen Dank für diese Gelegenheit. Das Studium Eurer Waffe hat mir große Freude bereitet.\n\nAls Gegenleistung für das mir von Euch entgegengebrachte Vertrauen in meine Fähigkeiten habe ich unsere Forscher darum gebeten, die Forschungsnotizen für Euch in leicht verdauliche Portionen aufzuteilen. Wenn Ihr zusätzliche Ressourcen opfern könntet, bin ich mir sicher, dass wir in Zukunft weitere, noch wertvollerere Erkenntnisse zutage fördern werden.\n\nIch versichere Euch, dass jede Minute, die wir bisher in das Projekt investiert haben, es wert war.", sourceObjective = "Liefert genug Ordensressourcen ab, um einen Einführungskurs in Artefaktwissen abzuschließen.", progress = "Wenn Ihr mir mehr Ressourcen bringt, kann ich weitere Berichte über die Geschichte und das Potenzial Eurer Artefaktwaffe anfertigen.\n\nDieses Wissen braucht Ihr, um Eurer Waffe zusätzliche Macht zu verleihen.\n\nBringt mir diese Ressourcen so bald Ihr könnt. Die Legion muss fallen!", completion = "Die Ordensressourcen, die Ihr gebracht habt, sind unabdingbar, wenn Ihr Eure Waffe weiter verstärken wollt.\n\nNehmt diese Notizen. Lest Euch die Forschungsberichte durch und wendet das gelernte Wissen an.\n\nVorwärts zum Sieg!", sourceObjectiveStatus = "unverified-source-field" }
quests[46157] = { id = 46157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiterbildung", description = "Die Macht, die in diesen Artefakten steckt, ist unglaublich, und wir haben bisher nur an der Oberfläche gekratzt.\n\nUnsere Forscher waren damit beschäftigt, die entsprechenden Erkenntnisse für Euch aufzubereiten. Und ich bin mir sicher, dass wir mit ein paar mehr Ressourcen auch Informationsmaterial für Euch zusammenstellen können, mit dem Ihr Euer Artefaktwissen vermehren könnt.\n\nDas ist aber nur der erste Schritt, denn mit mehr Ressourcen können wir Euch noch viel tiefer in die Forschung eintauchen lassen.", sourceObjective = "Liefert genug Ordensressourcen ab, um einen Einführungskurs in Artefaktwissen abzuschließen.", progress = "Wenn Ihr mir mehr Ressourcen bringt, kann ich weitere Berichte über die Geschichte und das Potenzial Eurer Artefaktwaffe anfertigen.\n\nDieses Wissen braucht Ihr, um Eurer Waffe zusätzliche Macht zu verleihen.\n\nBringt mir diese Ressourcen so bald Ihr könnt. In Worten liegt Weisheit.", completion = "Die Ordensressourcen, die Ihr gebracht habt, sind unabdingbar, wenn Ihr Eure Waffe weiter verstärken wollt.\n\nNehmt diese Notizen. Lest Euch die Forschungsberichte durch und wendet das gelernte Wissen an.\n\nJede gute Geschichte braucht einen Helden!", sourceObjectiveStatus = "unverified-source-field" }
quests[46158] = { id = 46158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiterbildung", description = "Je weiter wir den Erzählungen in die Vergangenheit folgen, desto lauter werden die Stimmen, die vom unermesslichen Potenzial dieser Artefakte zeugen.\n\nWir haben bereits viel in Erfahrung gebracht, das wir weitergeben könnten. Weitere Ordensressourcen würden es uns außerdem ermöglichen, Informationen von unseren Mitgliedern zu sammeln, die allerorten nach weiteren Erkenntnissen forschen.\n\nSo wie Ihr sind diese Schamanen der Schlüssel zur Entfaltung des vollen Potenzials dieser Waffen. Und schon bald werden wir uns wieder der zeitraubenden Aufgabe widmen, weitere Gerüchte über sie zusammenzutragen.", sourceObjective = "Liefert genug Ordensressourcen ab, um einen Einführungskurs in Artefaktwissen abzuschließen.", progress = "Wenn Ihr mir mehr Ressourcen bringt, kann ich weitere Berichte über die Geschichte und das Potenzial Eurer Artefaktwaffe anfertigen.\n\nDieses Wissen braucht Ihr, um Eurer Waffe zusätzliche Macht zu verleihen.\n\nBringt mir diese Ressourcen so bald Ihr könnt. Der Wind führt uns zum Sieg!", completion = "Die Ordensressourcen, die Ihr gebracht habt, sind unabdingbar, wenn Ihr Eure Waffe weiter verstärken wollt.\n\nNehmt diese Notizen. Lest Euch die Forschungsberichte durch und wendet das gelernte Wissen an.\n\nMögen uns die Elemente zum Sieg führen!", sourceObjectiveStatus = "unverified-source-field" }
quests[46159] = { id = 46159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine dringende Nachricht", description = "Wir haben eine dringende Nachricht von einem von Belaths Spähern unten in Mardum erhalten! Ich glaube, Ihr solltet sie hören.", sourceObjective = "Aktiviert die Konsole, um die Nachricht aus Mardum zu erhalten.", completion = "Lady S'theno hat sich nach unten begeben, um zu helfen, aber es klingt, als ob es wirklich ernst wird!", sourceObjectiveStatus = "unverified-source-field" }
