quests[46172] = { id = 46172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greeting Kit" }
quests[46173] = { id = 46173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taktische Planung", description = "<Schlachtenfürst/Schlachtenfürstin> {name}! Wir sollten unsere nächsten Schritte besprechen!", sourceObjective = "Trefft Euch mit Odyn in der Großen Methalle der Himmelsfeste.", completion = "Es ist schön, Euch wiederzusehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46175] = { id = 46175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rollender Donner" }
quests[46176] = { id = 46176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Erzmagier behelligen", description = "Die Barriere ist überwunden! Damit ist Erzmagier Xylem endlich in Reichweite!\n\nHoffentlich wird er kooperieren und die Iris aushändigen...", sourceObjective = "Stellt Erzmagier Xylem.", sourceObjectiveStatus = "unverified-source-field" }
quests[46177] = { id = 46177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Portalreichweite", description = "Xylem ist vielleicht entkommen, aber die Spuren seines Portals sind noch da.\n\nNachdem Ihr nun seine Lehrlinge von der Verderbnis befreit habt, werde ich sie nach einem Weg suchen lassen, ihn aufzuspüren. Sobald ich etwas gefunden habe, werde ich die Kirin Tor alarmieren.\n\nIch möchte Euch nur darum bitten, den Erzmagier nicht zu töten, sollte es zu einem Kampf kommen. Ich glaube nämlich, dass er trotz des dunklen Schattens, der auf ihm lastet, immer noch ein guter Mann ist.\n\nLebt wohl, {name}.", sourceObjective = "Kehrt zu Erzmagier Kalec in Dalaran zurück.", completion = "Dann wurde Xylem also von der Schattenmagie verderbt und ist mit der fokussierenden Iris entkommen? Das ist nicht gut.\n\nDie Kirin Tor werden jetzt verstärkt mit seinen Lehrlingsen... ich meine Lehrlingen, zusammenarbeiten. Wir müssen den Erzmagier finden, bevor er einen großen Fehler macht.\n\nLasst uns Kontakt halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[46178] = { id = 46178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor aller Augen verborgen", description = "Seid gegrüßt, Schattenklinge.\n\nIch hoffe, Ihr seid nicht allzu verärgert, dass ich ohne Euch angefangen habe. Ich habe leichte Schwierigkeiten, mich angesichts der hirnlosen Untoten zu beherrschen.\n\nJa, Ihr habt mich richtig verstanden. Taerir, genau der Taerir, der jetzt seit vielen Monaten in der Halle der Schatten gestanden hat, war die untote Schachfigur eines Schreckenslords.\n\nUnd es gibt noch mehr von ihnen. Sie sind in unseren Städten, sie steigen in den Rängen der Aristokratie auf, legen an Macht und Einfluss zu und sind kaum aufzuspüren.", sourceObjective = "Ermordet die infiltrierenden Homunculi.", progress = "Eure Klinge ist noch nicht blutig genug.", completion = "Wir haben den Dämonen gezeigt, warum sie die Dunkelheit wirklich fürchten sollten. Jetzt hat Lord Rabenholdt etwas aus seiner persönlichen Sammlung für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[46179] = { id = 46179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legion vernichten" }
quests[46180] = { id = 46180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht unseres Feindes" }
quests[46182] = { id = 46182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht um den Hochberg", description = "Unsere Verteidigung ist immer stärker geworden, doch die Legion greift Donnertotem weiter an. Es gibt nur einen Weg, diesem Wahnsinn ein Ende zu bereiten. Wir müssen gemeinsam mitten ins Herz ihrer Streitkräfte schlagen und diese Angriffe beenden.", sourceObjective = "Besiegt Teufelskommandant Erixtol am Hochberg.", completion = "Unsere Bemühungen am heutigen Tag haben die Legion zurückgeschlagen, aber lasst uns nicht nachlässig werden. Unsere Reise hat gerade erst begonnen.", sourceObjectiveStatus = "unverified-source-field" }
