quests[46198] = { id = 46198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Edelsteine der Zerstörung" }
quests[46199] = { id = 46199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht um Azsuna", description = "Der widerwärtige Dämon, der den Angriff befehligt, muss aufgehalten werden. Ich kann uns nah heranbringen, aber sobald wir dort sind, benötige ich die Hilfe von Euch und Euren Verbündeten, um die dämonischen Streitkräfte auszuschalten.", sourceObjective = "Besiegt Teufelskommandant Xeritas in Azsuna.", completion = "Durch den Fall ihres Kommandanten wird es leichter für unsere Verteidiger sein, mit den Streitkräften der Legion in Azsuna zurechtzukommen. Dank Eurer Bemühungen werden wir diesen Angriffen vielleicht ein für alle Mal ein Ende setzen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[46200] = { id = 46200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Problem gelöst... vorerst...", description = "Ihr solltet zu den Kirin Tor zurückkehren. Sie wollen sicher von Eurem Erfolg erfahren. Ich werde Lord Erdris finden und mich dann bei Euch melden.", sourceObjective = "Sprecht mit Erzmagierin Modera in Dalaran.", completion = "Ich bin erleichtert, dass Ihr Euch um die unmittelbare Bedrohung gekümmert habt. Wir haben schon so kaum genug Ressourcen für die Verheerte Küste!\n\nDennoch haben wir etwas für Euch...", sourceObjectiveStatus = "unverified-source-field" }
quests[46201] = { id = 46201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch Wasser geläutert" }
quests[46202] = { id = 46202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rare Elite 14" }
quests[46205] = { id = 46205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbindungsabbruch", description = "Es bleibt uns noch eine letzte Aufgabe, um die Verbindung der Brennenden Legion zu den anderen Welten zu kappen.\n\nIch stelle Euch ein Transportmittel zur Verfügung, um Euch näher an die Energiequelle zu bringen, aber Ihr müsst der Verbindung den Todesstoß versetzen.", sourceObjective = "Zerstört die Legionsverbindung am Tempel der Tausend Lichter.", completion = "Jetzt, da die Verbindung zerstört ist, könnte sich unsere einzige Chance ergeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[46206] = { id = 46206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flüstern einer verängstigten Welt", description = "\"Champion! Azeroth braucht unsere Hilfe.\"\n\n<Magni Bronzebarts Worte hallen durch Euren Verstand, als würden sie aus uralten, längst vergangenen Zeiten zu Euch sprechen. Azeroths Weltenseele scheint dem Sprecher eine Warnung zukommen lassen zu wollen, aber irgendeine Kraft stört die Übermittlung dieser Botschaft.>\n\n<Magni hat Euch aufgefordert, in das Sholazarbecken, das lebhafte Herz des eingefrorenen Nordends, zu reisen, um ihm zu helfen.>", sourceObjective = "Trefft Euch mit Magni im Sholazarbecken und hört Euch die Warnung an.", completion = "Diese Warnung ist tatsächlich ein beängstigendes Omen, {name}. Das Schicksal Azeroths scheint mit jenem von Argus, der Heimatwelt der Legion, verbunden zu sein.\n\nWir müssen den Plan des Dunklen Titanen aufdecken! Ich glaube, die Verbindung des Sprechers mit der Weltseele ist hier von größter Bedeutung.\n\nBleibt wachsam, Hochlord. Wir müssen uns auf Magnis Rat verlassen... und auf den von Azeroth selbst.", sourceObjectiveStatus = "unverified-source-field" }
quests[46207] = { id = 46207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung des Zorns", description = "Ich möchte Euch eine prestigeträchtige Einladung aussprechen.\n\nJedes Jahr lasse ich meinen besten Krieger eine Prüfung durchlaufen, um zu beweisen, dass ich die Stärksten des Landes befehlige. Ich habe Euch als meinen Champion für diese Prüfung erwählt.\n\nSolltet Ihr sie erfolgreich absolvieren, wartet auf Euch am Ende ein Preis, der Euren Leistungen angemessen ist.\n\nNehmt Euch Zeit, um Euch vorzubereiten. Kommt zurück und sprecht mich an, wenn Ihr bereit seid, zu beginnen.", sourceObjective = "Sprecht mit Odyn, um das Szenario \"Prüfung des Zorns\" zu beginnen. Schließt das Szenario ab und beansprucht Euren Preis.", completion = "Das war wahrlich eine großartige Zurschaustellung der Fähigkeiten eines Kriegers. Ich war sehr beeindruckt davon, wie Ihr mit Asrea fertiggeworden seid. Sie wird uns fehlen.\n\nAber nun zu einem noch größeren Ereignis: dem Preis, der Euch rechtmäßig zusteht.", sourceObjectiveStatus = "unverified-source-field" }
quests[46208] = { id = 46208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine göttliche Einladung", sourceObjective = "Sprecht mit Odyn in Eurer Ordenshalle in der Himmelsfeste.", completion = "Schlachtenfürst {name}, ich möchte Euch ein Angebot unterbreiten, das Euch gefallen könnte...", sourceObjectiveStatus = "unverified-source-field" }
quests[46209] = { id = 46209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Leuchtfeuer im Dunklen" }
quests[46212] = { id = 46212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoch mit ihnen" }
quests[46213] = { id = 46213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristalle nicht enthalten", description = "Turalyon ist in Sicherheit und wir können jetzt zurückschlagen.\n\nAber als Erstes müssen wir so viele Vorräte wie möglich an der Absturzstelle sichern.\n\nWir sind zwar vom Licht gesegnet, aber unsere Schiffe basieren immer noch auf Kristalltechnologie. Um unsere Verteidigung und unsere Waffen zu verstärken, müssen wir so viele davon einsammeln wie möglich, wenn wir unsere Feinde zurückschlagen wollen.\n\nBegebt Euch zur Absturzstelle und sammelt alle Kristalle ein, die Ihr finden könnt. Und haltet da draußen auch Ausschau nach Y'mera. Sie wurde von uns getrennt und wird sicher Hilfe brauchen können.", sourceObjective = "Sammelt 10 Argunitkristalle.", progress = "Ich hoffe, Ihr habt genügend Verstärkung mitgebracht.", completion = "Ihr habt die Kristalle dabei? Dem Licht sei Dank. Das ist genau, was wir jetzt brauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[46216] = { id = 46216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geronnene Verderbnis" }
