quests[46234] = { id = 46234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valarjar Lore Unlock 6" }
quests[46235] = { id = 46235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesicherte Umgebung", description = "Jetzt, wo Lexera besiegt wurde, wird sich ihre Fallenstellerbande schnell auflösen. Und jene, die sich weigern, dürfen mit meiner Klinge Bekanntschaft schließen.\n\nDiese Küste wird frei sein von jenen, die Azeroths Tierwelt verderben wollen.\n\nVorerst ist unsere Arbeit an diesem Ort getan. Trefft mich an der Retterklippe. Ich möchte in sicherer Umgebung weitere Dinge mit Euch besprechen.", sourceObjective = "Trefft Nachtjägerin Syrenne an der Retterklippe.", completion = "Ihr habt hier an der Verheerten Küste in kürzester Zeit so viel erreicht. Beeindruckend, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[46236] = { id = 46236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steingebundene Soldaten" }
quests[46237] = { id = 46237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutbringers Sendschreiben", description = "<Hexenmeister/Hexenmeisterin>! Wir haben Neuigkeiten von der Schreckensnarbe.\n\nEine Nachricht von Mor'zul Blutbringer traf heute mit einem Raben hier ein. Darin steht die Anweisung, dass Ihr ihn sofort in der Schreckensnarbe aufsuchen sollt!", sourceObjective = "Sprecht mit Mor'zul Blutbringer in der Schreckensnarbe.", completion = "Unsere Aufgabe wird nicht leicht, aber wenn es vorüber ist, dann werden wir die wahren Herren von Xoroth sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[46238] = { id = 46238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn Ihr es baut", description = "Wenn wir eine dauerhafte Verbindung nach Xoroth aufbauen wollen, brauchen wir ein ganz besonders widerstandsfähiges Portal. Leider können wir so eines nicht einfach so herbeibeschwören.\n\nIhr müsst die notwendigen Materialien beschaffen. Sobald wir diese haben, werde ich dafür sorgen, dass es von den Mo'arg sofort gebaut wird.\n\nHier ist die Liste der Dinge, die Ihr benötigt.", sourceObjective = "Sammelt 5 Stück Teufelsschiefer, 3 Chaosspinelle und einen unbeugsamen Trank. Diese können entweder selbst gesammelt oder durch Handwerksfertigkeiten hergestellt oder im Auktionshaus gekauft werden.", progress = "Habt Ihr die notwendigen Materialien?", completion = "Ausgezeichnet. Dieser unbeugsame Trank sollte den Teufelsschiefer genügend verstärken, damit er die Bausubstanz des Portals trägt, und diese Chaosspinelle müssten die Magie des Portals wunderbar konzentrieren.\n\nIch werde die Mo'arg schleunigst an die Arbeit schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[46239] = { id = 46239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des Teufels Kern", description = "Es ist für einen Hexenmeister zwar relativ einfach geworden, einen kurzfristigen Durchgang in ein Reich der Legion zu öffnen, aber für ein dauerhaftes Portal ist erheblich mehr Kraft erforderlich.\n\nDafür werden wir eine Energiequelle benötigen, die voller Teufelsenergie steckt.\n\nIch weiß, dass die Kommandanten der Legion mächtige Teufelskerne verwenden, um ihre Kriegsschiffe zu steuern. Wenn Ihr den Kommandanten eines dieser Schiffe besiegt, solltet Ihr den Kern an Euch nehmen können.", sourceObjective = "Beschafft einen überladenen Teufelskern vom Kommandanten eines Angriffs der Legion auf den Verheerten Inseln.", progress = "Habt Ihr den Kern?", completion = "Ich spürte die vom Kern ausgehende Teufelsenergie sofort, als Ihr die Schreckensnarbe betreten habt.\n\nIch denke, er wird unseren Ansprüchen genügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46240] = { id = 46240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Öl ins Feuer gießen", description = "Ein mächtiger Kern allein wird nicht ausreichen, um das Portal mit Energie zu versorgen. Wie jeder starke Motor wird er Treibstoff benötigen. Ein Teufelsenergiemotor muss allerdings Lebenskraft verbrennen, um zu laufen.\n\nWir brauchen mit magischer Energie angereichertes Blut, damit unser Teufelskern in Gang bleibt und unsere Verbindung nach Xoroth aufrechterhält. Glücklicherweise bin ich in diesen Dingen erfahren und kenne genau den richtigen Ort, wo wir so etwas bekommen können.\n\nIhr werdet eine Art Gefäß brauchen.", sourceObjective = "Sammelt 50 Einheiten Eulenbestienblut von Eulenbestien in der Schummerlichtgrotte in Val'sharah.", progress = "Habt Ihr die Eulkin ausbluten lassen?", completion = "Das... ist ganz schön viel Blut. Ich bin beeindruckt, {name}.\n\nIch sollte wirklich anfangen, das Zeug zu lagern. Es gibt so viele Verwendungen dafür!", sourceObjectiveStatus = "unverified-source-field" }
quests[46241] = { id = 46241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schergen von Hel'nurath", description = "Schreckenslord Hel'nurath beschenkt seine Leutnants mit Rufsteinen, damit sie die Schreckensrösser von Xoroth herbeirufen und an sich binden können. Ich glaube, ein derartiger Stein wird uns dabei helfen, das Zornross hervorzulocken.\n\nEinige xorothianische Kultisten wurden gesehen, wie sie die Legion an der Verheerten Küste unterstützen. Man kann sicherlich davon ausgehen, dass ihr Anführer einen von Hel'nuraths Steinen bei sich trägt.\n\nEuer Sukkubus sollte die Wahrheit aus den Kultisten herauslocken können. Findet einen, der weiß, wo sich sein Anführer aufhält.", sourceObjective = "Benutzt die Verführung Eures Sukkubus, um xorothianische Kultisten innerhalb der Dunklen Palisaden an der Verheerten Küste zu befragen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46242] = { id = 46242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf des Schreckenslords", description = "Den Angaben des Kultisten zufolge müsste die von Euch gesuchte Anführerin sich in ihrem Turm befinden, um die Vorgänge an den Dunklen Palisaden zu überblicken.", sourceObjective = "Beschafft einen xorothianischen Rufstein von Zuriwa der Verhexerin innerhalb der Dunklen Palisaden an der Verheerten Küste.", progress = "Ich nehme an, Ihr habt den Stein gefunden?", completion = "Ich habe lange gewartet, um einen der Rufsteine des Schreckenslords in den Händen zu halten. Gäbe es unsere aktuelle Aufgabe nicht, könnten wir eine ganze Armee mit Schreckensrössern ausstatten.\n\nDieser hier wird allerdings einem höheren Ziel dienen. Sobald es den Lockruf des Steins vernimmt, wird Arax'ath das Zornross nicht mehr bändigen können. Wir müssen nur das Portal lange genug offen halten, dann wird es kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46243] = { id = 46243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Zornross von Xoroth", description = "Die Zeit ist gekommen und die Vorbereitungen sind abgeschlossen. Wenn Ihr bereit seid, werden wir in Xoroth ein Loch reißen und Arax'ath und das Zornross zwingen, aus ihrem Versteck zu kommen.\n\nFolgt mir zur Beschwörungsplattform. Dort werden wir das Ritual beginnen.\n\nWappnet Euch, {name}. Das wird kein einfaches Unterfangen.", sourceObjective = "Beendet das Ritual auf der Beschwörungsplattform in der Schreckensnarbe, um das Zornross zu versklaven.", completion = "Das Zornross ist bereit, von Euch unterworfen zu werden, Netherfürst. Es wird sich nicht so einfach versklaven lassen, denn es hat einen starken Willen.\n\nIch gebe zu, dass ich ein wenig neidisch bin. So ein prachtvolles Tier habe ich nie zuvor gesehen. Unsere Jünger hatten große Mühe, es unter Kontrolle zu halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[46244] = { id = 46244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kathedrale der Ewigen Nacht: Der Altar der Aegis", description = "Champion, wir sind bereit, das Grabmal des Sargeras anzugreifen.\n\nIch habe die Schriften Aegwynns studiert, der Wächterin, die den Avatar des Dunklen Titanen einst besiegte. Darin steht, dass es für den Fall, dass ihr Zauberschutz negiert wird, eine Sicherung gibt. Diese kann ausgelöst werden, indem man die Aegis von Aggramar auf einem Altar in der Kathedrale der Ewigen Nacht platziert.\n\nIhr seid <der Held, der/die Heldin> die; die Säulen der Schöpfung geborgen hat. Versammelt Eure Verbündeten und begebt Euch in die Kathedrale. Seid auf der Hut: Mephistroth wird seine gesamte Macht einsetzen, um Euch daran zu hindern, die Aegis dort zu platzieren. Ihr müsst siegreich sein!", sourceObjective = "Besiegt Lord Mephistroth und platziert die Aegis von Aggramar auf dem Altar der Ewigen Nacht.", completion = "Mephistroth ist tot und die Kathedrale ist gesichert, doch die unteren Bereiche des Grabmals verbleiben in den Händen der Legion.\n\nWir hatten uns einen anderen Ausgang erhofft, aber der Kampf ist noch lange nicht vorbei, {name}.\n\nLasst nicht nach. Zeigt der Legion keine Gnade und lasst ihr keinen Ausweg. Wenn wir bereit sind, werden wir das Grabmal einnehmen und sie aus Azeroth vertreiben!", sourceObjectiveStatus = "unverified-source-field" }
quests[46245] = { id = 46245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baubeginn", description = "Wir haben die Vorräte. Jetzt muss jemand entscheiden, was wir damit anstellen.\n\nHmm. Dieser Jemand seid wohl Ihr, als {class}t und so!\n\nSucht ein Gebäude aus, auf das wir uns konzentrieren sollen.", sourceObjective = "Benutzt den Zeichentisch, um Kriegsvorräte der Legionsrichter für den Bau des Magierturms, des Netherdisruptors oder der Kommandozentrale bereitzustellen.", progress = "He! Welches Gebäude sollen wir bauen?\n\nIch muss hier Termine einhalten!", completion = "Eine hervorragende Wahl! Nicht, dass es eine schlechte Wahl gäbe, aber es ist immer gut, das Positive herauszustreichen, wenn man von endlosen Horden mordlustiger Dämonen umgeben ist.\n\nKommt wieder zurück, wenn Ihr weitere Vorräte gesammelt habt, dann weise ich sie der Befestigung Eurer Wahl zu.\n\nUff! Mein Hals ist ganz trocken von all dem Gerede. Zeit, mir ein wenig die Kehle zu schmieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[46246] = { id = 46246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Streckt sie nieder", description = "Der Teufelssturm lässt weiter dämonischen Abschaum auf diese Küste herabregnen. Kil'jaeden glaubt, sein Heer wäre endlos und seine Ressourcen unerschöpflich.\n\nWir werden ihm zeigen, wie sehr er sich da irrt.\n\nSchlagt eine Schneise der Vergeltung durch ihre Reihen, {class}t. Streckt einen Dämon nach dem anderen nieder, bis Eure Waffen vor deren Blut triefen. Und wenn sie um Gnade betteln, schickt Ihr sie schreiend zurück in den Nether.", sourceObjective = "Tötet 100 Dämonen an der Verheerten Küste.", completion = "Ich habe ein ganzes Leben damit verbracht, die Niederträchtigen zu jagen und sie für ihre Verbrechen bezahlen zu lassen. Wenn ich einen Dämon niederstrecke, spüre ich, dass Gerechtigkeit geübt wurde.\n\nIhr wart heute ein Werkzeug der Vergeltung, Meisterjäger. Wenn Ihr Euch für ein anderes Leben entschieden hättet, wärt Ihr vielleicht ein würdiges Mitglied in unseren Reihen geworden.", sourceObjectiveStatus = "unverified-source-field" }
quests[46247] = { id = 46247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigung der Verheerten Inseln", description = "In unserem Eifer, der Legion die Verheerte Küste wieder zu entreißen, können wir nicht zulassen, dass der Rest des Landes den widerwärtigen Dämonen in die Hände fällt.\n\nKil'jaeden hat seine Streitkräfte in jeden Winkel der Verheerten Inseln entsandt und gefährdet die Heimat Eurer neuen Verbündeten. In dieser Stunde der Not müsst Ihr ihrem Ruf folgen.\n\nZerschlagt diese Dämonenangriffe auf schnellstem Wege, {class}t. Die Legionsrichter werden für die Sicherheit der Verheerte Küste sorgen.", sourceObjective = "Schließt einen Dämonenangriff auf den Verheerten Inseln ab.", completion = "Ein großartiger Sieg, Erzmagier.\n\nDoch ruht Euch nicht auf Euren Lorbeeren aus! Kämpft gegen die Legion, wo immer sie auch zuschlägt.", sourceObjectiveStatus = "unverified-source-field" }
quests[46248] = { id = 46248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine sich selbst bewahrheitende Prophezeiung", description = "In meinem Leben habe ich viele Visionen erblickt. Einige haben mich mit Hoffnung erfüllt... andere mit Verzweiflung.\n\nDer Sieg über Kil'jaeden ist zum Greifen nah. Ich habe ihn vorhergesehen, doch zeigen uns Visionen nur mögliche Wege. Sie auch umzusetzen, erfordert harte Arbeit.\n\nDiese obliegt Euch, {name}. Ihr habt schon viel erreicht, doch mehr ist vonnöten. Kämpft auf den Schlachtfeldern der Verheerten Küste und schmiedet ein Schicksal für uns, in dem wir aus dem Griff der Legion befreit sind!", sourceObjective = "Schließt Weltquests an der Verheerten Küste ab.", completion = "Schritt für Schritt marschieren wir auf den Sieg zu. Wir dürfen nicht nachlassen!\n\nNur mit Mut und Beharrlichkeit können wir das niederträchtige Böse aufhalten, das die Seele dieser Welt bedroht.", sourceObjectiveStatus = "unverified-source-field" }
quests[46249] = { id = 46249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champions für unsere Sache", description = "Euer Orden hat wichtige Arbeit geleistet, {class}t. Eure Champions haben es wieder und wieder geschafft, der Legion das Handwerk zu legen.\n\nWährend wir den Angriff auf das Grabmal des Sargeras vorbereiten, müssen wir die Dämonen weiter bedrängen. Wenn wir wieder und wieder Druck ausüben, entdecken wir Schwachstellen, die wir zu unserem Vorteil nutzen können.\n\nSendet die Champions Eures Ordens aus, {name}. Ihre Missionen sind wichtig für den Erfolg unserer Kampagne... umso mehr, je näher unsere Begegnung mit Kil'jaeden rückt.", sourceObjective = "Schließt eine Mission der Legionsrichter in Eurer Klassenordenshalle erfolgreich ab.", completion = "Hervorragend, Hochlord! Wenn wir diesen Krieg endlich gewonnen haben, schulde ich Euch und Euren Champions wohl ein Bankett zu Ehren Eurer Heldentaten.\n\nMoment. Das klang jetzt sehr nach diesem Odyn. Wobei ich ihn selbst natürlich noch nie getroffen habe...", sourceObjectiveStatus = "unverified-source-field" }
quests[46250] = { id = 46250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Kopf abschlagen", description = "An der Verheerten Küste wimmelt es von Abschaum der Legion, und jeder Dämon hat ein schnelles und gnadenloses Ende verdient.\n\nEinige sind aber listiger als der Rest. Mächtige Kämpfer mobilisieren andere für ihre widerwärtigen Zwecke.\n\nStreckt diese dämonischen Champions nieder und erfüllt den Rest mit Angst und Zweifel. Brecht den Kampfgeist der Legion, dann brechen wir ihr auch das Genick.", sourceObjective = "Tötet seltene Elitekommandanten der Dämonen an der Verheerten Küste.", completion = "Wir müssen jede Gelegenheit nutzen, den Willen von Kil'jaedens Heer zu untergraben.\n\nWenn sie sehen, wie ihre mächtigsten Champions zu Staub zerfallen, begreifen sie vielleicht, dass ihre berüchtigte Legion dem Untergang geweiht ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[46251] = { id = 46251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Splitterwochen", sourceObjective = "Sammelt 2500 Nethersplitter an der Verheerten Küste.", progress = "Habt Ihr die Splitter? Ich hoffe, Ihr habt genau mitgezählt. Wenn Ihr Euch verzählt habt, kann ich nicht dafür garantieren, was passiert.", completion = "Man hat mich darauf aufmerksam gemacht, dass ich es bisweilen ein wenig übertreibe.\n\nDas... <räuspert sich> war womöglich soeben der Fall.\n\nEin einziger Nethersplitter genügt für meine Zwecke. Mit dem Rest könnt Ihr sicherlich noch etwas Sinnvolles anfangen.\n\nLasst uns diese Angelegenheit baldigst vergessen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46252] = { id = 46252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verseuchung verbannen", description = "Während wir den Abschaum der Legion an der Verheerten Küste beseitigen, behalten die Unholde die Lande in der Nähe fest im Griff. Wir dürfen sie nicht länger dulden.\n\nDie stinkenden Festungen von Faronaar und die Teufelsseelenbastion verseuchen ganz Azsuna und Suramar. Wählt einen Angriffspunkt und schlagt eine Schneise durch ihre niederträchtigen Reihen.\n\nKehrt zu mir zurück, wenn Eure Hände mit Dämonenblut bedeckt sind, dann können wir unsere Kampagne fortsetzen, um Kil'jaeden aus dem Grabmal zu treiben.", sourceObjective = "Tötet 50 Dämonen in Faronaar oder der Teufelsseelenbastion.", completion = "Wenn wir die Reihen der Dämonen an Standorten wie Faronaar und der Teufelsseelenbastion ausdünnen, nehmen wir der Legion ihr Standbein.\n\nKil'jaeden wird fallen!", sourceObjectiveStatus = "unverified-source-field" }
quests[46253] = { id = 46253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Säulen der Schöpfung", description = "Unsere Kampagne an der Verheerten Küste hat einen Wendepunkt erreicht. Die Legionsrichter sind bereit, das Grabmal des Sargeras zu stürmen und das Einfallstor der Legion in unsere Welt zu versiegeln.\n\nJetzt ist es an der Zeit für den Angriff, {name}.\n\nDie Aegis von Aggramar wurde in der Kathedrale gesichert. Das Echo von Magna Aegwynn hat uns mitgeteilt, dass die anderen Säulen der Schöpfung benötigt werden, um das Grabmal zu versiegeln. Es ist nur angemessen, dass Euch die Ehre zuteilwird, die uralten Relikte einzusetzen und damit den Teufelssturm ein für alle Mal zu beenden.", sourceObjective = "Benutzt die Säulen der Schöpfung, um das Grabmal des Sargeras zu versiegeln.", progress = "Der Invasion der Legion muss ein Ende gesetzt werden.", completion = "Die Säulen der Schöpfung sind jetzt platziert. Das Grabmal des Sargeras ist versiegelt und Aegwynns Echo hat seinen Frieden gefunden.\n\n<Khadgar deutet zum Himmel.>\n\nLeider ist uns ein solcher Luxus nicht vergönnt.\n\nIhr habt heute zwar einen großen Sieg errungen, aber wir haben keine Zeit zum Feiern. Die letzte Schlacht erwartet uns. Macht Euch bereit.", sourceObjectiveStatus = "unverified-source-field" }
quests[46254] = { id = 46254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "TBD" }
quests[46255] = { id = 46255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "X instabile Portale gestört, 1 Weltboss besiegt" }
quests[46256] = { id = 46256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "X Schätze gefunden, 1 Herausforderung versucht" }
quests[46257] = { id = 46257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "NEU VERWENDEN" }
quests[46258] = { id = 46258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ruhe nach dem Sturm", description = "Ihr habt die Elemente davor bewahrt, unter die Kontrolle der Legion zu fallen, und dafür danken wir Euch. Doch das hat einen hohen Preis gefordert, sowohl was Euer eigenes Wohl als auch das Eurer Schamanen betrifft. Viele kehrten verwundet zu uns zurück, mitgeschleift von anderen Schamanen.\n\nWir haben das Chaos gesehen, das der Verdammnisstein anrichten kann. Er gehört nicht in die Hände irgendeines Wesens, egal ob sterblich oder nicht. Während Ihr geschlafen habt, haben die Elementarlords und ich über sein Schicksal beraten.\n\nBringt ihn zu Neptulon. Er wird Euch alles erklären.", sourceObjective = "Bringt den Verdammnisstein zu Neptulon im Mahlstrom.", completion = "Ihr habt das Zerstörungspotenzial des Verdammnissteins selbst erlebt. Ihr zählt zu den erfahrensten Wächtern Azeroths, aber auch in Euren Händen hat diese Macht für Chaos und Panik gesorgt. Stellt Euch nur vor, was jemand mit finsteren Absichten damit anstellen könnte...\n\nDas dürfen wir nicht zulassen.\n\nWir haben diskutiert, wie mit dem Artefakt zu verfahren ist, während wir auf Euer Erwachen warteten. Wir hatten überlegt, den Stein in eine der Elementarebenen zu bringen, aber sie alle bergen Gefahren.\n\nHier ist er am sichersten verwahrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[46259] = { id = 46259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkelbinderdilemma", description = "Ah, Delas hat Euch geschickt. Verstehe.\n\nGut, dass sie nicht selbst gekommen ist. Es würde ihr das Herz brechen, wenn sie mit ansehen müsste, was aus unserer Familie geworden ist.\n\nEine Dämonin entweiht unsere Toten in den Ruinen in der Nähe. Mit ihrer Teufelsmagie verwandelt sie unsere Vorfahren in hirnlose Schrecken, die dem Willen der Brennenden Legion folgen.\n\nGegen diese Harpyien und den Dämon komme ich nicht an, aber könnt Ihr vielleicht helfen?\n\nWenn Ihr die Dunkelbinderin beseitigt, die unsere Toten peinigt, überlasse ich Euch all die verbleibenden Relikte der Familie Mondfang.", sourceObjective = "Tötet Dunkelbinderin Elissath.", progress = "Unsere Toten werden nie in Frieden ruhen, solange Dunkelbinderin Elissath noch lebt.", completion = "Ihr habt meinen Dank, {name}. Die Familie Mondfang hat schon bessere Zeiten erlebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[46260] = { id = 46260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit den Schatten verschmelzen", description = "Wir sollten uns wieder dem Rest des Rats anschließen und ihnen berichten, was wir an diesem Tag erreicht haben. Kehrt zu uns zurück, wann immer es Euch beliebt. Wir werden auf Euch warten.", sourceObjective = "Kehrt zur Halle der Schatten zurück und sucht Lord Jorach Rabenholdt auf.", completion = "Wir haben über Eure Erfolge in der letzten Zeit gesprochen, {name}. Wir bewegen uns in den Schatten und das wird oft als selbstverständlich angesehen. Doch ohne uns hätten es die Legionsrichter mit weitaus mehr mächtigen Dämonen zu tun.\n\nWir brauchen den Ruhm nicht. Wir ernten den Lohn.", sourceObjectiveStatus = "unverified-source-field" }
quests[46261] = { id = 46261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geschmack der Verderbnis" }
quests[46262] = { id = 46262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet die Kaulquappen!" }
quests[46263] = { id = 46263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsnetze spinnen" }
quests[46264] = { id = 46264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie haben uns im Auge" }
quests[46265] = { id = 46265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteufelte Rehkitze" }
quests[46266] = { id = 46266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr des Rächers", description = "Fallss Ihr mir nur ein wenig ähnlich seid, freut Ihr Euch sicher, fessten Boden unter Euren Füßen zu spüren!\n\nLeider aber solltet Ihr wohl lieber gleich zur Teufelsshammer zurückkehren, damit Kor'vass sich um die Reparaturen kümmern kann.", sourceObjective = "Kehrt zu Kor'vas an Bord der Teufelshammer zurück.", completion = "Mit Euren flinken Klingen habt Ihr wieder einmal Euren Wert für die Illidari unter Beweis gestellt, Rächer {name}. Wir werden sofort die Reparaturen an der Teufelshammer in Angriff nehmen.\n\nWir dürfen nicht zulassen, dass die Legion uns erneut unvorbereitet erwischt!", sourceObjectiveStatus = "unverified-source-field" }
quests[46267] = { id = 46267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr des Schlachtenfürsten", description = "<Schlachtenfürst/Schlachtenfürstin> {name}, Odyn möchte von Euch die Geschichten über Eure glorreichen Siege hören!\n\nIch helfe Euch, in die Himmelsfeste zurückzukehren, sobald Ihr dazu bereit seid!", sourceObjective = "Sprecht mit Odyn in der Himmelsfeste.", completion = "Eure Rückkehr ist wahrlich triumphal, Schlachtenfürst {name}.\n\nUnter Eurer Führung sind die {class} der Himmelsfeste in der Tat eine ernst zu nehmende Streitmacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[46268] = { id = 46268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein gefundenes Andenken", description = "<Die schöne, bronzene Außenseite des Kleinods weist komplizierte und filigrane Einlegearbeiten auf, obwohl Felsen und Wellen viele der Einzelheiten zerstört haben. Ihr wischt den Schmutz und das Salz fort, die den Verschluss verkrusten, und öffnet es.\n\nEs ist ein Kompass - oder wenigstens war es früher einer. Die Glasoberfläche ist zersplittert, die Nadel ist verbogen und bewegt sich nicht.\n\nIn den Deckel ist ein Porträt eingelassen. Die Farbe ist verblasst und das Bild verschwommen, doch das Motiv ist unverkennbar: das Gesicht des jungen Anduin Wrynn.>", sourceObjective = "Bringt den Kompass zu König Anduin Wrynn in der Burg Sturmwind.", progress = "Ich grüße Euch, {name}. Was führt Euch heute nach Sturmwind?", completion = "<Der König untersucht den Kompass und sein Gesichtsausdruck wechselt von Erkennen zu Trauer.>\n\nAls ich die Sachen meines Vaters durchsuchte und diesen Kompass nicht fand, nahm ich an, dass er ihn an der Verheerten Küste bei sich trug, als Gul'dan...\n\n<Dem König versagt die Stimme.>", sourceObjectiveStatus = "unverified-source-field" }
quests[46270] = { id = 46270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "reuse me" }
quests[46272] = { id = 46272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einbestellung in die Burg", description = "Seid gegrüßt, {name}.\n\nEure Anwesenheit wird am königlichen Hof erbeten. Die Krone benötigt dringend Eure Dienste!\n\nBitte kehrt so bald wie möglich nach Sturmwind zurück.\n\nKönig Graumähne erwartet umgehend Eure Ankunft.", sourceObjective = "Sprecht mit Genn Graumähne in der Burg Sturmwind.", completion = "Endlich seid Ihr hier, Erzdruide!\n\nEurer Aufmerksamkeit ist es vielleicht nicht entgangen, dass König Anduin sich momentan durch Abwesenheit hervortut.\n\nNur Ihr könnt diese Situation wieder ins Lot bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46273] = { id = 46273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Questgeber" }
quests[46274] = { id = 46274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den König trösten", description = "Seit Ihr Anduin den Kompass gebracht habt, ist er nicht mehr derselbe. Er ist teilnahmslos geworden... abwesend.\n\nWir haben vergeblich versucht, ihn zu trösten. Gestern Morgen verließ er die Burg, ohne ein Wort zu sagen.\n\nIch befahl natürlich den Wachen, ihm zu folgen. Er ging zur Kathedrale, um zu beten, und dort hält er sich seitdem auf.\n\nIhr habt diese Melancholie über ihn gebracht! Ihr müsst den Jungen davon überzeugen, seinen Pflichten wieder nachzukommen. Wir haben einen Krieg zu gewinnen!", sourceObjective = "Sucht nach König Anduin Wrynn in der Kathedrale von Sturmwind.", completion = "Lasst mich raten... Genn hat Euch geschickt.\n\nIch frage mich, was ihm wichtiger ist... mein Wohlergehen oder den Anschein zu wahren, dass alles normal ist?", sourceObjectiveStatus = "unverified-source-field" }
quests[46275] = { id = 46275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herz eines Königreichs", description = "Mein Vater war eine Legende. Er überwachte den Wiederaufbau von Sturmwind, stand Drachen von Angesicht zu Angesicht gegenüber und führte die Allianz zu zahllosen Siegen.\n\nDann, eines Tages, war er einfach... weg.\n\nIch trage seine Krone, ich trage seinen Titel. Aber ich habe nichts getan, um beides zu verdienen... oder das Vertrauen meines Volks.\n\nIch habe den Krieg einsam in der Burg verbracht, umgeben von Wachen und Ratgebern. Ich muss durch die Straßen von Sturmwind laufen, um zu erfahren, ob Hoffnung oder Angst in den Herzen meines Volks schlägt.\n\nIch würde Eure Gesellschaft begrüßen.", sourceObjective = "Begleitet König Anduin auf seinem Gang durch Sturmwind.", completion = "Sie haben recht. Sie haben vollkommen recht.", sourceObjectiveStatus = "unverified-source-field" }
quests[46277] = { id = 46277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helft beim Bau des Magierturms" }
quests[46278] = { id = 46278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück an den Absender", description = "Ihr seid gerade rechtzeitig eingetroffen!\n\nAnders als die Post in letzter Zeit, befürchte ich.\n\nWir haben viel zu wenig Personal und die Nachfrage war nie höher. Wir können einfach nicht mithalten!\n\nIch würde gern plaudern, aber ich brauche Hilfe, um mit der Arbeit nachzukommen, bevor ich mir auch nur einen Moment Ruhe gönnen kann.\n\nZuerst das Wichtigste: Einige Bündel unzustellbare Post sind verloren gegangen. Könnt Ihr mir helfen, sie einzusammeln und ihren Absendern zuzustellen?", sourceObjective = "Bringt 9 unzustellbare Briefe zurück.", completion = "Ihr seid ein Naturtalent!\n\nWürdet Ihr noch ein Weilchen bleiben? Ich könnte hier wirklich eine helfende Hand gebrauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[46279] = { id = 46279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zargrom" }
quests[46282] = { id = 46282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Königs", description = "Jetzt, da ich die Verheerte Küste und die Schrecken der Legion mit eigenen Augen gesehen habe, erkenne ich die Wahrheit.\n\nIch spreche nicht von dem unfassbaren Übel unseres Feindes, sondern dem Mut und der Aufopferung, die solches Übel in den Herzen unseres Volkes bewirkt hat.\n\nMein Vater sagte mir einmal: Jeder König muss das Gewicht seiner eigenen Krone tragen. Noch nie hat die meinige so schwer auf meinem Haupt gelastet, wie in diesem Moment...\n\nBitte führt mich zu der Stelle, an der mein Vater starb, damit ich sein Opfer ehren kann.", sourceObjective = "Begleitet König Anduin zum Grabmal des Sargeras.", completion = "Ich kann Euch kaum sagen, wie sehr Ihr mir geholfen habt, {name}. Dafür werdet Ihr für immer meinen Dank haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[46283] = { id = 46283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.2 Broken Shore - Buildings - Mage Tower - Personal Reward Received" }
quests[46286] = { id = 46286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der Legionsrichter", description = "Wenn wir keine ordentlichen Befestigungen bauen, werden wir nicht lange hier an der Verheerten Küste durchhalten.\n\nDas lasse ich nicht zu, da könnt Ihr Gift drauf nehmen!\n\nWir haben mit dem Bau an drei bedeutenden Gebäuden begonnen: dem Magierturm, dem Netherdisruptor und der Kommandozentrale. Jedes dieser Gebäude wird uns dabei helfen, die Brennende Legion unangespitzt in den Boden zu rammen.\n\nUm den Bau voranzubringen, brauchen wir Kriegsvorräte der Legionsrichter... und zwar haufenweise! Bringt sie mir, ich kümmere mich um die Verteilung. Alles klar?", sourceObjective = "Schließt Weltquests an der Verheerten Küste ab oder tötet seltene Elitegegner, um Kriegsvorräte der Legionsrichter zu verdienen.", progress = "Ja, sieh einer an! Habt Ihr mir Kriegsvorräte der Legionsrichter mitgebracht?", completion = "Jawohl, genau so habe ich mir das vorgestellt!\n\nNa, dann mal an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[46288] = { id = 46288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alle an die Front" }
quests[46290] = { id = 46290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr des Erzmagiers", description = "Jetzt, wo Dalaran wieder geschützt ist, können wir alle ein wenig durchatmen.\n\nEs ist an der Zeit, dass wir zur Halle des Wächters zurückkehren. Ich bin sicher, Meryl erwartet schon gespannt die Nachricht von Eurem Erfolg.", sourceObjective = "Sprecht mit Meryl in der Halle des Wächters.", completion = "Wir dürfen nicht vergessen, dass es sich hierbei um eine vorübergehende Maßnahme handelt. Ich kann gar nicht ausreichend betonen, wie groß die Zerstörung wäre, sollte Kathra'natir entkommen...\n\nTrotzdem, dank Euch haben Dalarans Zähne wieder einen kräftigen Biss. Gut gemacht, Erzmagier {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[46291] = { id = 46291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Todesminen schlagen zurück", description = "Breanni schickt Euch? Für sie sind Informationen immer kostenlos. Aber haltet mich nicht für einen Spitzel.\n\nIch hänge schon seit Jahren bei den Todesminen herum. Meistens kann ich da eine ruhige Kugel schieben. Aber vor ein paar Tagen habe ich alle möglichen Geräusche aus den Minen kommen hören. Wenn Ihr da unbemerkt reinwollt, nehmen wir einen Minenwagen und sausen da runter, ohne dass uns jemand groß beachtet.\n\nSagt mir einfach Bescheid, wenn Ihr einsteigen wollt.", sourceObjective = "Besiegt Krümels Essensreste in den Todesminen.", completion = "Jemand hat etwas aus Krümels Kessel genommen? Ich werde sofort Breanni informieren. Offensichtlich war das Vorkommnis in den Höhlen des Wehklagens kein Einzelfall. Es geht etwas Großes vor, und ich glaube, Ihr seid unwissentlich mitten da reinmarschiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[46292] = { id = 46292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haustierkampfherausforderung: Todesminen", description = "In den Todesminen müsste immer noch etwas aufgeräumt werden. Offensichtlich habt Ihr das beim letzten Mal nicht ganz geschafft.\n\nWir könnten wieder den Trick mit dem Minenwagen verwenden. Aber dieses Mal peppen wir das noch etwas auf. Wie wär's mit Feuer? Nein? Also gut, dann nicht. Sagt mir einfach Bescheid, wenn Ihr bereit seid.", sourceObjective = "Besiegt Krümels Essensreste in den Todesminen.", completion = "Beeindruckende Arbeit. Hier sind die Vorräte, die ich Euch versprochen habe. Ich glaube, diese schattenhafte Gestalt hat sie zurückgelassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46293] = { id = 46293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesminen, Teil Drei?", description = "Ich habe verdächtige Geräusche aus den Todesminen kommen hören. Nach Eurem Galaauftritt in den Höhlen des Wehklagens seid Ihr die perfekte Person, um dieser Sache nachzugehen!\n\nIch habe einen Freund in Westfall. Er sieht zwar nicht so aus, aber er ist blitzgescheit und hat vielleicht mehr Informationen darüber, was in Westfall vor sich geht. Wir hatten schon mit den van Cleefs zu tun... sogar zweimal. Was also sorgt da unten für diese Unruhe?", sourceObjective = "Findet Marcus \"Taschmann\" Braun außerhalb der Todesminen in Westfall.", completion = "Ich weiß nichts! Überhaupt nichts! Ihr solltet lieber abhauen, bevor Euer Gesicht mein Messer kennenlernt! Was wollt Ihr eigentlich von mir? Ich krieg' eh nicht so viel mit!\n\nOh, Breanni? Ja, klar! Sie ist eine alte Freundin von mir!", sourceObjectiveStatus = "unverified-source-field" }
quests[46297] = { id = 46297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überwältigende Kraft", description = "Auf dieser Welt werden wir keinen sicheren Ort finden. Die Streitkräfte der Brennenden Legion schwellen immer weiter an, um Argus zu verteidigen.\n\nDas Belagerungslager da unten ist voller Dämonenabschaum, der zwischen uns und der auf der Vindikaar vorbereiteten Waffe steht.\n\nWir müssen sie auslöschen, bevor sie vollständig aufgeladen werden kann, oder Argus wird unser Grab sein.", sourceObjective = "Tötet 12 Dämonen.", completion = "Und jetzt zur Hauptwaffe.", sourceObjectiveStatus = "unverified-source-field" }
quests[46304] = { id = 46304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rare Elite 15" }
quests[46305] = { id = 46305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thorims Flamme", description = "Vor nicht allzu langer Zeit haben die Drekirjar und die Thorignir einander noch respektiert. Das hat sich erst geändert, als Skovald an die Macht kam. Ein uralter Geist der Drekirjar wacht nun über den Gipfel, bei dem es sich um eine Art heiligen Friedhof zu handeln scheint. Er ist der Hüter der zeremoniellen Flamme und genau die benötigen wir, um die Brutmutter herauszulocken.\n\nSollen wir gehen und ihn überzeugen, uns die Flamme zu überlassen? Ich bin sicher, er wird uns gegenüber äußerst... freundlich sein.", sourceObjective = "Überzeugt den Schreinhüter der Drekirjar, Euch Thorims Flamme zu überlassen.", completion = "Seht Ihr? Absolut überzeugt. Jetzt lasst uns die Fackel zum Leuchtfeuer bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46308] = { id = 46308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Spur hinterlassen" }
quests[46313] = { id = 46313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rare Elite 16" }
quests[46314] = { id = 46314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rachsucht: Auf der Suche nach Kor'vas", description = "Zum Glück sind wir nicht die Einzigen, die die Verschwörungen der Legion zur Infiltration der Stadt aufdecken.\n\nKor'vas Blutdorn, eine Eurer Illidari, hat begonnen, alleine die Straßen zu patrouillieren, um den Ursprung der jüngsten Angriffe aufzuspüren.\n\nSo ganz traue ich den Euren nicht über den Weg, aber ich muss eingestehen, dass Ihr Eurem Namen alle Ehre gemacht habt. Ich schlage vor, Ihr sucht Kor'vas auf und seht, was sie herausgefunden hat, bevor die Legion erneut zuschlägt.", sourceObjective = "Findet Kor'vas Blutdorn in den Straßen von Dalaran.", completion = "Rächer {name}, ich bin so froh, Euch zu sehen.\n\nWir müssen schnell vorgehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[46315] = { id = 46315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prideful Gladiator's Leather Armor" }
quests[46316] = { id = 46316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Kanrethad Schwarzhaupt", sourceObjective = "Ich erinnere mich an Euch, {name}. Wir haben uns vor langer Zeit im Schwarzen Tempel getroffen. Wie könnte ich solche Macht nur vergessen!\n\nDeshalb war es auch die richtige Entscheidung des Rates, Euch während meiner Abwesenheit als Anführer zu erwählen.\n\nMacht Euch keine Sorgen, ich habe kein Verlangen, gegen diese Entscheidung zu argumentieren. Ich schulde Euch mein Leben.\n\nLasst mich Euch und dem Rat dienen. Es gibt noch so viel, was wir voneinander lernen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[46317] = { id = 46317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Kralle", description = "Die Legion startet erneut einen Angriff auf den Schrein von Aviana am Hyjal!\n\nThisalee Krähe organisiert eine Gegenoffensive und bittet um Eure alsbaldige Anwesenheit im Hain der Träume.\n\nWir kümmern uns hier um die Offensive. Viel Glück, <Erzdruide/Erzdruidin>!", sourceObjective = "Sprecht mit Thisalee Krähe im Hain der Träume.", completion = "Erzdruide! Wir haben nicht viel Zeit, der Schrein steht schon in Flammen!", sourceObjectiveStatus = "unverified-source-field" }
quests[46318] = { id = 46318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigung von Aviana", description = "Die Lage ist fatal. Die Legion greift ERNEUT den Schrein von Aviana auf dem Hyjal an! Sie müssen etwas Bestimmtes im Auge haben, doch ich weiß nicht, was es sein könnte.\n\nWir Druiden der Kralle sind erfahrene Späher und Infiltratoren, aber es fehlt uns an... Robustheit. Sie werden nicht lange durchhalten können! Wir müssen ihnen helfen!", sourceObjective = "Helft Thisalee bei der Verteidigung des Schreins von Aviana auf dem Hyjal und kehrt dann zu ihr in den Hain der Träume zurück.", completion = "Die Legion wird für das, was wir heute verloren haben, büßen. Wir sind mit so vielen von uns wie möglich geflohen, aber zu viele sind vergeblich gestorben, während sie versuchten, den Schrein und den Götzen von Aviana zu verteidigen. Beide waren dank dieses Dämonenabschaums Schattenhain ohnehin verloren.", sourceObjectiveStatus = "unverified-source-field" }
quests[46319] = { id = 46319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Himmel nehmt Ihr mir nicht", description = "Der Schrein von Aviana ist an die Dämonen gefallen und der Götze von Aviana wurde gestohlen.\n\nDer Götze funktioniert als Verbindung zwischen den Druiden der Kralle und den Flugfähigkeiten, die uns von Aviana verliehen wurden.\n\nDie Druiden der Kralle haben beschlossen, einen neuen Schrein an einem sichereren Ort zu bauen: hier im Hain der Träume.\n\nWährenddessen werde ich unseren Götzen zurückholen. Trefft Euch mit mir in Azsuna nahe der Stelle, bis zu der wir Infazzar verfolgt haben.", sourceObjective = "Vernichtet Infazzar den Schemen und holt den Götzen von Aviana zurück.", progress = "<Platziert den verderbten Götzen von Aviana auf dem Sockel.>", completion = "Ihr platziert den verderbten Götzen von Aviana auf dem Sockel.", sourceObjectiveStatus = "unverified-source-field" }
quests[46320] = { id = 46320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoffnung auf Heilung", description = "Hoffentlich habt Ihr genug Proben Teufelsgift gefunden, um ein Heilmittel zu brauen.\n\nWir treffen uns im Tempel der Fünf Sonnenaufgänge wieder!", sourceObjective = "Kehrt zum Geist von Braumeisterin Blanche in den Tempel der Fünf Sonnenaufgänge zurück.", completion = "Hmm, lasst mich mal sehen... Ja, ich glaube, das lässt sich neutralisieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[46321] = { id = 46321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krasus' Landing Searched" }
quests[46322] = { id = 46322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Piratenbucht", description = "Da wir an der Verheerten Küste mittlerweile Fortschritte gemacht haben, denke ich, dass es jetzt an der Zeit für einige der subtileren Taktiken der Ungekrönten ist.\n\nWir haben von einer großen Höhle auf dem Festland erfahren, wo mächtige Dämonen Pläne für unseren Niedergang schmieden. Eine unserer Schurkinnen, Lilian Voss, hat mit Tethys eine Strategie ausgearbeitet, um mit ihnen fertigzuwerden, aber dafür brauchen sie Eure Hilfe. Sie warten auf Euch in des Toten Manns Bucht in Azsuna.", sourceObjective = "Trefft Euch mit Lilian Voss und Tethys in des Toten Manns Bucht in Azsuna.", completion = "Endlich... mein Spezialgebiet. Wir werden das richtig angehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46323] = { id = 46323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist da drin?", description = "Unser Ziel ist es, einen Behälter voll Schießpulver zu beschaffen, das mit einer Art Teufelskraft versetzt worden ist. Ich weiß nicht, wie die Piraten in seinen Besitz gelangt sind, aber es ist gefährlicher, als sie ahnen. Ich versichere Euch, es wird in unseren Händen viel... wirkungsvoller sein.\n\nIhr solltet Meisterschützin Prix am hinteren Ende der Bucht antreffen, nahe des Wassers. Nehmt ihr ab, was wir brauchen.", sourceObjective = "Tötet Meisterschützin Prix und nehmt den Behälter mit teufelsberührtem Schießpulver an Euch.", progress = "Habt Ihr es?", completion = "Ja... das Schießpulver. Es ist der Schlüssel zu meinem Plan!", sourceObjectiveStatus = "unverified-source-field" }
quests[46324] = { id = 46324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefälschte Befehle", description = "Wir müssen einige Vorsichtsmaßnahmen ergreifen. Sobald Ihr die Schützin ausschaltet, wird die Mannschaft nach Euch suchen. Ich habe Tethys angewiesen, ein paar gefälschte Befehle in ihrer Handschrift anzufertigen, die uns etwas Zeit verschaffen sollten.\n\nDeponiert diese Befehle an den markierten Orten. Das wird die Gefahr entschärfen.", sourceObjective = "Platziert die gefälschten Befehle an den markierten Plätzen.", completion = "Sie sind so eifrig losgezogen... Dummköpfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[46325] = { id = 46325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die vereinte Front" }
quests[46326] = { id = 46326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf zu Jorach", description = "Und somit ist die erste Phase meiner Intrige abgeschlossen. Kehren wir zu Jorach zurück und sagen ihm, dass es Zeit ist, weiterzumachen.", sourceObjective = "Kehrt zu Lord Jorach Rabenholdt in der Halle der Schatten zurück.", completion = "Willkommen zurück, Schattenklinge. Ich gehe davon aus, dass Ihr das Schießpulver besorgt habt?", sourceObjectiveStatus = "unverified-source-field" }
quests[46327] = { id = 46327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Handel mit den Schatten", description = "Die von Euch zusammengetragenen Hinweise deuten darauf hin, dass Levia in der Bibliothek unter Dalaran ein Ritual durchführen wollte... vermutlich, um diese \"Agatha\" zu beschwören, in die sie so vernarrt ist. Ich fürchte, das überschreitet mein Wissen, also werde ich jemanden um einen Gefallen bitten müssen.\n\nIch werde Unterstützung vom Rat der Schwarzen Ernte erbitten. Einer ihrer Hexenmeister wird sich mit Euch in der Kammer des Wächters treffen, um Euch bei Eurer Untersuchung zu helfen.\n\nIch hoffe, dass wir noch nicht zu spät sind.", sourceObjective = "Trefft Ritssyn Flammengroll in der Kammer des Wächters unter Dalaran.", completion = "Ihr habt ein Glück, dass Modera mich um Unterstützung gebeten hat.\n\nAgatha ist zu viel für Euch, {class}. Sie ist zu viel für jeden von uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[46328] = { id = 46328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[46329] = { id = 46329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[46330] = { id = 46330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[46331] = { id = 46331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[46333] = { id = 46333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Am Rande des Abgrunds", sourceObjective = "Kehrt zur Teufelshammer zurück und sprecht mit Matronenmutter Malicia.", completion = "Rächer {name}, es gibt da etwas, das ich gerne mit Euch besprechen würde, wenn Ihr einen Moment erübrigen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[46334] = { id = 46334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein teuflisch guter Fund", description = "Mardum birgt eine Menge Geheimnisse und eins davon haben wir vor nicht allzu langer Zeit aufgedeckt, kurz nachdem wir die Kontrolle über die Teufelshammer übernommen hatten. Es ist eine Art Brutstätte, die von Teufelsfledermäusen nur so wimmelt.\n\nWir haben die Jungtiere gefangen und versucht, sie für unsere Zwecke gegen die Legion abzurichten.\n\nDoch vor einigen Tagen haben wir etwas noch Besseres erbeutet... etwas, das Eurer Stellung angemessen ist, <Rächer/Rächerin>.\n\nSprecht mit Kyra und sie wird dafür sorgen, dass Ihr zum Teufelsschwingenvorsprung kommt.", sourceObjective = "Sprecht mit Kyra Lichtklinge, um zum Teufelsschwingengrat transportiert zu werden. Schließt dann das Szenario \"Der Teufelsschwingengrat\" ab.", completion = "Ich hätte es nicht für möglich gehalten, dass man eine erwachsene Teufelsfledermaus zähmen könnte, aber Ihr habt offenbar das Gegenteil bewiesen. Das ist eine vielversprechende Entdeckung für uns.\n\nDoch für den Moment solltet Ihr erst einmal alle sehen lassen, was Ihr vollbracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[46335] = { id = 46335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schatzkammer der Tirisgarde", description = "Dalarans Waffen mögen arkanen Ursprungs sein, doch das heißt noch lange nicht, dass wir nicht auch andere Optionen nutzen können.\n\nIn der Schatzkammer unseres Ordens befindet sich eine Vielzahl magischer Geräte... Schaut Euch doch einfach mal dort um und seht, ob Ihr etwas Nützliches entdecken könnt.", sourceObjective = "Findet 5 uralte Artefakte in der Halle des Wächters.", progress = "Habt Ihr etwas Vielversprechendes entdeckt?", completion = "Also das nenne ich mal eine bunte Sammlung!\n\nDie sind alle auf ihre eigene Art mächtig, das ist wahr, aber keins davon entspricht unseren Anforderungen. Zumindest nicht in der jetzigen Form.\n\nIch frage mich...", sourceObjectiveStatus = "unverified-source-field" }
quests[46336] = { id = 46336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine goldene Eintrittskarte", description = "<Meisterjäger/Meisterjägerin>, uns wurde aus der Hütte zugetragen, dass auf einem der Tische ein aus goldenem Licht gewirkter Brief liegt, der Euren Namen trägt.\n\nNiemand weiß genau, wie er dort hingelangt ist. Jemandes Wolf hat wohl versucht, ihn zu öffnen, und hat dafür eine Menge versengtes Fell ums Maul herum vorzuweisen. Scheinbar ist der Brief nur für Eure Augen bestimmt.\n\nWir werden hier unten die Stellung halten, während Ihr nachseht.", sourceObjective = "Lest den goldenen Brief in der Volltrefferhütte.", completion = "<Vorsichtig hebt Ihr den glänzenden Brief auf und öffnet ihn.>", sourceObjectiveStatus = "unverified-source-field" }
quests[46337] = { id = 46337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nacht der Wildnis", description = "<Der Brief ist in einer fließenden, goldenen Schrift verfasst. Ihr könnt beinahe hören, wie Odyns donnernde Stimme die Worte ausspricht, während Ihr sie lest.>\n\nDie Nacht der Wildnis ist angebrochen.\n\nHeute Abend werden wir zu Ehren der legendären Wildtiere ein Festmahl abhalten, und sie werden sich erneut auf den Feldern der Ewigen Jagd erheben.\n\nEiner von uns wird auf die Felder hinausgehen, um einmal mehr ihre Geister zur Ruhe zu betten.\n\nMein Herold erwartet Euch, <Jäger/Jägerin>, falls Ihr Euch uns anschließen möchtet.", sourceObjective = "Bittet den Herold von Odyn, Euch zu den Feldern der Ewigen Jagd zu bringen.", completion = "<Ein Sattel liegt hier bereit, ganz so, als würde er auf Euren neuen Gefährten warten.\n\nIhr fühlt eine warme Verbundenheit mit dem Tier, als Ihr an Eure Zusammenkunft zurückdenkt, und wisst, was Ihr tun müsst, um den Wolfsfalken herbeizurufen. Ihr legt Eure Finger an die Lippen...>", sourceObjectiveStatus = "unverified-source-field" }
quests[46338] = { id = 46338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine kreative Lösung", description = "Der Seelenstein der Nachtgeborenen könnte unsere beste Chance darstellen, sofern wir einen Weg finden, ihn zu nutzen, ohne dass Kathra'natir dabei entkommt. Wenn er in Dalaran freikommen würde...\n\nWir sollten es mit unserer Freundin Ari besprechen. Sie wird wissen, was für Modifikationen notwendig sein werden.", sourceObjective = "Sprecht mit Ari.", completion = "Also hat sich die Botschaft über Ryanna schon verbreitet? Ha!", sourceObjectiveStatus = "unverified-source-field" }
quests[46339] = { id = 46339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlüsselmeister Orlis", description = "Die teufelsgeborenen Aufrührer bewachen anscheinend eine Teleportationsplattform auf der Lichtung kurz vor uns. Wohin diese wohl führt?\n\nWir können uns sicher sein, dass wir erst Schlüsselmeister Orlis ausschalten müssen, bevor wir darauf Zugriff erhalten.", sourceObjective = "Tötet Schlüsselmeister Orlis und durchsucht seinen Leichnam.", progress = "Habt Ihr etwas gefunden?", completion = "Es scheint sich um eine Art Einstimmungskristall zu handeln. Ausgezeichnet.", sourceObjectiveStatus = "unverified-source-field" }
quests[46340] = { id = 46340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tore sind verschlossen", description = "Wir müssen Sigryn erreichen, bevor sie Odyn stellen kann, doch der Weg ist uns versperrt. Odyn wird die Pforte der Tapferkeit schließen, sobald er von Sigryns Angriff erfährt. Wir müssen einen anderen Weg in die Hallen finden.\n\nIch kenne mich mit Portalen nicht aus, doch Eure Freunde von den Kirin Tor scheinen darin geübt zu sein. Geht zu ihnen und findet einen Weg hindurch.\n\nIch danke Euch für alles, was Ihr für Sigryn bereits getan habt, {class}. Es bleibt nur zu hoffen, dass wir sie auch vor ihr selbst retten können.", sourceObjective = "Kehrt zu Erzmagier Khadgar in der Violetten Zitadelle in Dalaran zurück.", completion = "Also trat Skovalds Tochter in die Fußstapfen ihres Vaters? Eine Schande, aber es war vielleicht unvermeidlich. Ich glaube, dies könnte der \"Fall\" sein, der in den Schriftrollen erwähnt wird.\n\nWenn dies stimmt, gibt es noch Hoffnung! Ich werde daran arbeiten, einen Weg in die Hallen der Tapferkeit für uns zu finden, damit wir Sigryn folgen können. Ich melde mich, sobald ich weiß, wie.\n\nIn der Zwischenzeit habt Ihr eine Belohnung verdient, denn Ihr habt uns einen großen Dienst erwiesen, indem Ihr sie bis hierher begleitet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[46341] = { id = 46341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geschichte von Ban-Lu", description = "Oh, hallo, Ihr müsst wohl <der neue Großmeister/die neue Großmeisterin> sein.\n\n<Meister Bu betrachtet Euch mit zusammengekniffenen Augen und schnuppert.>\n\nIhr Jünglinge habt einfach keine Geduld mehr, rennt dauernd umher und stürzt Euch in große Schlachten.\n\nKeine Zeit für Geschichten, nicht einmal die guten, was?\n\nGönnt Euren Fäusten doch einen Augenblick Ruhe und hört einem alten Mann bei einer Geschichte zu.\n\nVielleicht wollt Ihr dem alten Mann dabei ja auch noch ein Getränk spendieren?", sourceObjective = "Hört Euch Meister Bus Geschichte an.", completion = "Danke, dass Ihr zugehört und mir das Getränk spendiert habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[46342] = { id = 46342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Verheerten Gipfel", description = "Natürlich ist das nicht nur eine Geschichte. Ban-Lu hat allen vorherigen Großmeistern als persönliches Reittier gedient und sie als treuer und vertrauter Gefährte auf ihren Reisen begleitet.\n\nAber... er hat sich noch nicht gezeigt, seit Ihr <Großmeister/Großmeisterin> geworden seid. Das ist beunruhigend.\n\nEr wurde nicht mehr gesehen, seit er sich nach dem Fall von Großmeister Hight auf dem Gipfel der Ruhe befand.\n\nDort müssen wir die Suche nach ihm beginnen.", sourceObjective = "Trefft Euch mit Meister Bu am Gipfel der Ruhe.", completion = "Was für ein sinnloser Verlust... und wofür überhaupt?\n\n<Meister Bu sieht betrübt zum Portal und schüttelt den Kopf.>", sourceObjectiveStatus = "unverified-source-field" }
quests[46343] = { id = 46343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ban-Lus Spur", description = "Es ist schon eine Ewigkeit her, dass Großmeister Hight diese Lande bewandert hat.\n\nObwohl Ban-Lu all den früheren Großmeistern diente, bestand eine besondere Freundschaft zwischen ihm und Hight.\n\nViele Jahre lang reisten sie durch die Welt, trafen ihre Bewohner und hielten den zerbrechlichen Frieden aufrecht.\n\nIch kann mir nicht vorstellen, wie sehr sein Tod Ban-Lu getroffen hat.\n\nIrgendwo hier muss es Hinweise darauf geben, wo er sich befindet. Seht Euch gut um.", sourceObjective = "Folgt der Spur von Ban-Lu.", completion = "Meine morschen Knochen brauchen nur eine kleine Pause. Aber wir sind auf unserer Reise schon einen Schritt vorangekommen.\n\nDer Grummel dort drüben scheint ein wenig Unterstützung zu brauchen. Warum sprecht Ihr nicht mit ihm, während ich mich ein wenig ausruhe?", sourceObjectiveStatus = "unverified-source-field" }
quests[46344] = { id = 46344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stinkis Glücksbringer", description = "Ihr da! Hilfe! Dummer Ho-zen hat Stinkis Glücksbringer geklaut!\n\nJetzt ist Stinki für immer vom Pech verfolgt. Gerade umgedreht und schaut her, Rucksack in Flammen.\n\nWerd' das Feuer nicht löschen, dann kommt nur ein ANDERES Unglück. Vielleicht was Schlimmeres!\n\nIhr verprügelt Ho-zen, ja? Bringt Glücksbringer zurück? Stinki hilft Euch, so gut er kann!", sourceObjective = "Sammelt 3 Teile von Stinkis Glücksbringer.", progress = "Schon meinen Glücksbringer gefunden? Wird hier langsam etwas heiß.", completion = "Stinki hat neue Idee! Lässt Rucksack brennen!\n\nSolange der brennt, passiert nichts anderes Schlimmes! Brennender Rucksack IST Stinkis neuer Glücksbringer! Alten könnt Ihr behalten.\n\nOh, Ihr sucht nach großem Tiger? Stinki hat großen, leuchtenden Tiger gesehen. Lief Richtung Kloster. War Stinki hilfreich?", sourceObjectiveStatus = "unverified-source-field" }
quests[46345] = { id = 46345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinein ins Hornissennest", description = "Ich hoffe, Ihr seid bereit für ein Abenteuer. Sollen wir herausfinden, wohin der Teleporter uns führt?", sourceObjective = "Benutzt die Teleportationsplattform.", completion = "Ich glaube, wir haben ihr Hauptquartier entdeckt. Seid vorsichtig hier drinnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[46346] = { id = 46346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schatten von Ban-Lu", description = "Es war sehr nett von Euch, Stinki Bergspitz zu helfen, <Großmeister/Großmeisterin>. Noch dazu haben wir mehr über das Schicksal von Ban-Lu erfahren.\n\nIch werde Euch nicht damit zur Last fallen, mich zum Shado-Pan-Kloster zu eskortieren. Das schaffe ich auch allein.\n\nTreffen wir uns dort und setzen unsere Suche fort.", sourceObjective = "Trefft Euch mit Meister Bu am Shado-Pan-Kloster.", completion = "Ich habe gerade erst mit meiner Meditation begonnen, Großmeister. Doch wir haben vielleicht eine neue Spur...", sourceObjectiveStatus = "unverified-source-field" }
quests[46347] = { id = 46347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einmal aufwishan, bitte!", description = "Ich habe mit den Shado-Pan gesprochen, und sie sind bereit, uns mit Informationen zu versorgen, wenn wir ihnen bei einer Aufgabe helfen.\n\nSprecht mit Kommandant Shen-Li. Während Ihr sie unterstützt, werde ich weiter meditieren.", sourceObjective = "Helft Kommandant Shen-Li mit den Resten des Sha.", completion = "Die Shado-Pan scheinen dankbar zu sein, Großmeister.\n\nSollen wir fortf... Was ist das da für schwarzes Zeug an Eurem Fuß?", sourceObjectiveStatus = "unverified-source-field" }
quests[46348] = { id = 46348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fluss zu Ban-Lu", description = "Wir wissen immer noch nicht, wohin Ban-Lu verschwunden ist, aber ich kenne jemanden, der es wissen könnte.\n\nIm Südosten wohnt ein Jinyu, Wassersprecher Ryuli.\n\nVielleicht hat er Ban-Lu gesehen oder wir könnten ihn bitten, den Fluss zu fragen, wo man Ban-Lu in letzter Zeit gesehen hat?\n\nDieses Herumreisen hat meinen alten Knochen gewaltig zugesetzt, <Großmeister/Großmeisterin>. Ich werde mich hier noch etwas ausruhen und dann später zu Euch aufschließen.", sourceObjective = "Trefft Euch mit Wassersprecher Ryuli im Südosten.", completion = "Seid gegrüßt. Ich erhalte nicht alle Tage Besuch von einem Großmeister der Mönche. Wie kann ich Euch behilflich sein?", sourceObjectiveStatus = "unverified-source-field" }
quests[46349] = { id = 46349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lilien für Ryuli", description = "Ich habe Ban-Lu nicht gesehen, aber das Wasser wird sicherlich wissen, wo er sich aufhält.\n\nEs gibt eine Blume, die in den Seen an den Hängen in der Nähe des Tempels des Weißen Tigers wächst und nur in der Gegenwart eines reinen Herzens erblüht.\n\nBringt mir sechs dieser Mondlilien und ich werde sie verwenden, um mit dem Fluss zu sprechen.", sourceObjective = "Sammelt 6 Mondlilien für Wassersprecher Ryuli.", progress = "Was macht die Mondliliensammlung, Großmeister?", completion = "Danke. Erlaubt mir, für Euch nach Antworten zu suchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46350] = { id = 46350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung des Ban-Lu", description = "Ah, ich verspüre starke Wellen im Wasser! Der Tropfen fällt nicht weit von unserem Standort.\n\nBan-Lu ist nahe.\n\n<Ryuli schließt seine Augen und legt die Lilien ins Wasser. Sie bewegen sich langsam Richtung Osten.>\n\nEr wartet bereits auf Euch, am Fuße des Wasserfalls im Osten.", sourceObjective = "Findet Ban-Lu am Fuße des Wasserfalls.", completion = "Es wird mir eine Ehre sein, Euch über den Zeremonienpfad vom Schrein zum Tempel zu tragen, wie ich es schon für die Großmeister vor Euch getan habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[46351] = { id = 46351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ist es geheim, ist es sicher", description = "Es steckt mehr hinter dem Schildgenerator, den Ihr entdeckt habt, als man meinen würde. Ich glaube nicht, dass meine Ältesten erlauben würden, solche Technik mit Fremdlingen zu teilen...\n\nAber dennoch... Wir schulden Euch unser Leben und unsere Freiheit.\n\nIhr habt meine Erlaubnis, ihn zu nutzen. Doch... bitte haltet seine Existenz geheim, <Erzmagier/Erzmagierin> {name}.", sourceObjective = "Kehrt zu Ari in die Halle des Wächters zurück.", completion = "Was ist das?\n\nDas ist kein einfacher Schildgenerator... Das ist fast... ein fühlendes Wesen...\n\nUnd es erwartet begierig eine Aufgabe. Ja, ich glaube, es wird bereitwillig mit uns zusammenarbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[46352] = { id = 46352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vindictive Combatant's MailArmor" }
quests[46353] = { id = 46353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bu!", description = "Seid gegrüßt. Mir wurde gerade mitgeteilt, dass Meister Bu von einer langen spirituellen Reise zurückgekehrt ist und sich ein wenig in Morgenhauch außerhalb des Tempels der Fünf Sonnenaufgänge ausruht.\n\nEs ist eine ganze Weile her, dass jemand ihn gesehen oder von ihm gehört hat, aber er will mit Euch sprechen.\n\nIn Eurer Abwesenheit werden wir uns um die Situation hier kümmern, <Großmeister/Großmeisterin>.", sourceObjective = "Trefft Euch mit Meister Bu in Morgenhauch außerhalb des Tempels der Fünf Sonnenaufgänge.", completion = "Danke, dass Ihr gekommen seid, Großmeister.", sourceObjectiveStatus = "unverified-source-field" }
quests[46354] = { id = 46354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vindictive Combatant's Mail Armor" }
quests[46355] = { id = 46355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cataclysmic Gladiator's Chain Armor" }
quests[46356] = { id = 46356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vindictive Combatant's Dragonhide Armor" }
quests[46357] = { id = 46357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vindictive Combatant's Dragonhide Armor" }
